  str_voice_1202261_34 = "Coaxo! Coaxo!",
  str_voice_1202261_35 = "Coaxo! Coaxo!",
  str_voice_1202261_36 = "Coaxo! Coaxo!",
  str_voice_1202261_37 = "Coaxo! Coaxo!",
  str_voice_1202261_38 = "Coaxo! Coaxo!",
  str_voice_1202261_39 = "Coaxo! Coaxo!",
