  str_voice_1202261_41 = "Coaxo! Coaxo!",
  str_voice_1202261_42 = "Coaxo! Coaxo!",
  str_voice_1202261_43 = "Coaxo! Coaxo!",
  str_voice_1202261_44 = "Coaxo! Coaxo!",
  str_voice_1202261_45 = "Coaxo! Coaxo!",
  str_voice_1202261_46 = "Coaxo! Coaxo!",
  str_voice_1202261_47 = "Coaxo! Coaxo!",
  str_voice_1202261_48 = "Coaxo! Coaxo!",
  str_voice_1202261_49 = "Coaxo! Coaxo!",
  str_voice_1202261_50 = "Coaxo! Coaxo!",
  str_voice_1202261_51 = "Coaxo! Coaxo!",
  str_voice_1202261_52 = "Coaxo! Coaxo!",
  str_voice_1202261_53 = "Coaxo! Coaxo!",
  str_voice_1202261_54 = "Coaxo! Coaxo!",
  str_voice_1202261_55 = "Coaxo! Coaxo!",
  str_voice_1202261_56 = "Coaxo! Coaxo!",
  str_voice_1202261_57 = "Coaxo! Coaxo!",
  str_voice_1601774_1 = "Heheh... Ah, nada. Eu apenas me sinto feliz sempre que você está por perto!",
  str_voice_1601774_2 = "Gerente, Gerente, Gerente! É melhor você se acostumar a ouvir isso!",
  str_voice_1601774_3 = "Sabe, às vezes tenho muito medo do escuro, mas com você por perto, não temo nada.",
  str_voice_1601774_10 = "Brilha, brilha, você é a estrela mais brilhante que existe!",
  str_voice_1601774_11 = "Aqui vem Goldie! Sentiu minha falta, Gerente?",
  str_voice_1601774_12 = "Quer brincar de casinha? Eu serei a mãe, e você será o pai. Adicione o Marshmallow à mistura e - tada! Somos uma família de três!",
  str_voice_1601774_13 = "Espere, não se mexa... Ok, altura, tamanho... Posso fazer um travesseiro do seu tamanho? Assim, eu sempre me sentirei quente e aconchegante!",
  str_voice_1601774_14 = "Depois de usar fantasias por tanto tempo, é bom vestir pijamas macios e fofos às vezes - especialmente quando você está fazendo isso comigo!",
  str_voice_1601774_16 = "Pronto para começar o trabalho de hoje, PlayerName? Ops, eu deveria te chamar de \"Gerente\" por hoje!",
  str_voice_1601774_17 = "*boceja* Bom dia, você não quer tirar uma soneca comigo um pouco mais?",
  str_voice_1601774_18 = "Você tem trabalhado muito duro. Venha, eu tenho uma recompensa para você!",
  str_voice_1601774_19 = "O dia já acabou? Então vamos ter bons sonhos juntos.",
  str_voice_1601774_35 = "Deixe o concerto começar!",
  str_voice_1601774_36 = "Olá, amigos sonhadores!",
  str_voice_1601774_37 = "Deixe-me ver suas mãos!",
  str_voice_1601774_38 = "Cante comigo!",
  str_voice_1601774_39 = "Oh––Yay!",
  str_voice_1601774_40 = "Eu vou te destruir em nome do sonho!",
  str_voice_1601774_44 = "Gostaria de organizar um show de pijama aqui. Isso é ok, Gerente?",
  str_voice_1601774_58 = "Do-re-mi-fa-sol-la-si-do!",
  str_voice_1601774_59 = "Bom dia, gerente!",
  str_voice_1601774_60 = "Você vai se atrasar se não se levantar agora, Gerente!",
  str_voice_1601774_61 = "Bom dia! Todo dia é uma página em branco!",
  str_voice_1601774_62 = "Quer que eu cante uma canção de ninar para você?",
  str_voice_1601774_63 = "Fui uma estrela no palco hoje?",
  str_voice_1601774_64 = "Marshmallow quer dormir ao seu lado.",
  str_voice_1601774_65 = "Boa noite, Gerente!",
  str_voice_1601774_66 = "O pijama me faz ficar sonolento inconscientemente...",
  str_voice_1601774_67 = "Haha, o que você achou da minha dança?",
  str_voice_1601774_68 = "Mesmo em casa de pijama, você não pode relaxar!",
  str_voice_1601774_69 = "Onde você está, Marshmallow?",
  str_voice_1601774_70 = "*Tosse* Gerente, minha garganta...",
  str_voice_1601774_71 = "Qual é a sua opinião sobre as minhas novas músicas?",
  str_voice_1602233_1 = "May toda a beleza do mundo dance em seu nome, e May sua sábia liderança floresça por mil anos.",
  str_voice_1602233_2 = "Quando se trata de você, eu estaria disposto a conceder até mesmo um desejo um pouco caprichoso, se é algo que você realmente quer.",
  str_voice_1602233_3 = "Tais delícias encantadoras, tais jogos emocionantes. Neste vasto mundo de prazeres infinitos, por que alguém escolheria viver a amarga existência de uma divindade que essas antigas histórias glorificam tanto?",
  str_voice_1602233_10 = "À prova d'água, resistente ao frio, proteção térmica... Que outras formas de proteção alguém poderia conceder às suas roupas? Tais presentes raros devem ser valorizados e cuidados.",
  str_voice_1602233_11 = "Ah! A brisa é suave, a luz é quente e com você aqui, tudo é perfeito! Este é um dia que vale a pena lembrar, de fato.",
  str_voice_1602233_12 = "Vamos manter isso entre nós. Prometa-me que viverá muito e se juntará a mim em inúmeras aventuras mais emocionantes.",
  str_voice_1602233_13 = "Muitos rezam com corações cheios de raiva, tolice e ganância. Intenções puras como as suas são verdadeiramente raras.",
  str_voice_1602233_14 = "Seja a vida de um auroriano ou de um demônio, somos apenas grãos de poeira no vasto cosmos, indistinguíveis uns dos outros. Todos nós apenas saboreamos um momento fugaz no abraço do mundo.",
  str_voice_1602233_16 = "Muitos rezaram para mim, mas você é o primeiro a rezar por mim.",
  str_voice_1602233_17 = "Como está o tempo hoje? Se não estiver do seu agrado, permita-me mudar para você!",
  str_voice_1602233_18 = "Ah, as constelações de Longzhou... Há até uma entre elas chamada \"Chen.\"",
  str_voice_1602233_19 = "Você não deveria ficar acordado até tão tarde; é ruim para a sua saúde. Bem, acho que vou ter que te abençoar com boa saúde.",
  str_voice_1602233_35 = "Contemple, as cores vibrantes.",
  str_voice_1602233_36 = "Como desejar.",
  str_voice_1602233_37 = "Enquanto o dragão vagueia, mil marés surgem.",
  str_voice_1602233_38 = "Com um único pensamento, flores de lótus surgem.",
  str_voice_1602233_39 = "Vagueie pelo mundo ao seu lazer!",
  str_voice_1602233_40 = "Deleite-se com a melodia.",
  str_voice_1602233_44 = "Você não é um seguidor, você é um amigo, não é?",
  str_voice_1602233_58 = "A manhã chegou! Mais um dia tranquilo.",
  str_voice_1602233_59 = "Gostaria de se juntar a mim lá fora?",
  str_voice_1602233_60 = "Você está acordado, PlayerName?",
  str_voice_1602233_61 = "Ainda estou com sono... Talvez me ligue no próximo ano...",
  str_voice_1602233_62 = "A noite é para ouvir as ondas.",
  str_voice_1602233_63 = "Você não vai crescer alto se não dormir bem.",
  str_voice_1602233_64 = "Durma bem, PlayerName. Pronto, agora você nunca mais terá outro pesadelo.",
  str_voice_1602233_65 = "Você teve um dia divertido?",
  str_voice_1602233_66 = "Levantar-se com o sol e descansar ao anoitecer é um bom hábito.",
  str_voice_1602233_67 = "Certifique-se de usar os laços coloridos que eu te dei.",
  str_voice_1602233_68 = "Há muitos festivais em Longzhou... Vamos celebrá-los juntos na próxima vez.",
  str_voice_1602233_69 = "Ensine-me sua língua, PlayerName!",
  str_voice_1602233_70 = "Recebi uma oferta que nunca provei antes. Quer experimentar?",
  str_voice_1602233_71 = "Que oferendas... não, que presentes você gosta?",
  str_voice_1502281_1 = "\"O Último Celestita\"... Que título legal! Ah, se ao menos tivesse sido minha ideia...",
  str_voice_1502281_2 = "Claudius, Ethelred, Patroclus... Hmm, eu realmente tenho um gosto fantástico para nomes. Ah? Não é normal nomear as bombas?",
  str_voice_1502281_3 = "\"A vida é toda sobre velocidade e doçura. Isso faz com que correr enquanto come doces seja a verdadeira essência da vida.\" Linha bem legal, hein?",
  str_voice_1502281_4 = "Hehe! Eu sou a heroína destinada a salvar Astra, e depois de liberar o \"Selo da Noite Eterna\" da minha mão direita, serei ainda mais forte!",
  str_voice_1502281_5 = "Tornar-se um herói, é basicamente sobre amizade, trabalho duro, vitória e, claro, o aspecto mais importante - açúcar. Acho que me encaixo perfeitamente em todos esses aspectos.",
  str_voice_1502281_6 = "\"Neste momento, minha mão direita se acende. Em chamas, ela ruge, chamando por mim para...\" Qual é a próxima parte? Ah não, como eu poderia esquecer uma fala tão legal!?",
  str_voice_1502281_7 = "Você não é tão ruim. Coloque um pouco mais de esforço e eu posso considerar deixar você entrar no meu esquadrão de guerreiros!",
  str_voice_1502281_8 = "Reconheço seu poder, Último Celestita. A partir de hoje, você é um membro oficial do meu esquadrão e, como parte do seu rito de iniciação, você precisa compartilhar esse pirulito comigo!",
  str_voice_1502281_9 = "Uma vez que tudo isso acabar, você já pensou no que vai fazer em seguida? Se você ainda não planejou nada, que tal se juntar a mim... Ah não, é melhor eu não me amaldiçoar!",
  str_voice_1502281_10 = "Chaaaato... Eu quero correr... Não, talvez isso seja tudo parte de um verdadeiro teste de heroína... Eu não posso fugir agora.",
  str_voice_1502281_11 = "Hã? Você quer que eu fique aqui e espere como uma boa garotinha? Seja realista! Eu quero correr! Você insiste...? Você é grudento, mas tudo bem, eu vou ficar com você por um pouquinho, só um pouquinho, tá bom?",
  str_voice_1502281_12 = "Hmm, arroz com toffee foi um fracasso épico... Essa combinação é muito bizarra... Talvez eu deva tentar doces de frutas na próxima vez.",
  str_voice_1502281_13 = "Deixe-me ver... Que tal um doce de caramelo? Não, não—que tal doce de leite em vez disso!?",
  str_voice_1502281_14 = "Quer saber como comer tanto doce não apodreceu meus dentes? Hahaha, isso é porque eu sou o Ceifador Doce do Rediesel Wrench! Eu nunca negligenciaria minha higiene bucal!",
  str_voice_1502281_15 = "Feliz Aniversário! Então, onde está o bolo? Aquele com todo o creme e morangos!",
  str_voice_1502281_16 = "Hoje, assim como ontem, vou dar tudo de mim pelo destino do mundo!",
  str_voice_1502281_17 = "Bom dia... Yaaaawn... Estou tão sonolento. Você não se importa se eu tirar mais uma soneca, certo?",
  str_voice_1502281_18 = "O sol... se pôs, e agora, esses caras devem começar a se mexer, certo? Hã? Quem são esses caras? Bem... isso não importa—essa é a minha batalha, não interfira!",
  str_voice_1502281_19 = "Boa noite! Quer saber por que eu não estou dormindo? Porque eu sou todo crescido, e eu posso decidir se quero ir dormir cedo novamente!",
  str_voice_1502281_20 = "Cresci na Rediesel Wrench, então me dou bem com todos, exceto com aquela mulher... Hmph! Certo... toda heroína precisa de uma Nêmesis.",
  str_voice_1502281_21 = "Lumópolis? Ah... Claro que eu conheço! Derrotei um dragão maligno lá e salvei uma bela princesa!",
  str_voice_1502281_22 = "Viva a vida ao máximo! Sempre há tempo para doces!",
  str_voice_1502281_23 = "Não se preocupe, eu vou proteger todos! Afinal, eu derrotei três Eclipsitas quando tinha apenas nove anos.",
  str_voice_1502281_24 = "Azure... Ela é claramente um lacaio de algum senhor do mal... Mais cedo ou mais tarde, vou revelar seu verdadeiro rosto!",
  str_voice_1502281_25 = "As crianças na Rediesel Wrench são todos os meus subordinados.",
  str_voice_1502281_26 = "Proteger os doces do mundo é minha principal missão! Ah, doces de zero calorias e alcaçuz NÃO estão incluídos.",
  str_voice_1502281_27 = "Algo que eu não gosto...? Fracasso, eu acho...? Mas isso faz parte do desafio de uma heroína!",
  str_voice_1502281_28 = "Estou com tanta inveja... Então, esta é a superarma antiga do Último Celestita...",
  str_voice_1502281_29 = "Ah, guiado pela mão do destino, finalmente nos encontramos, lendário salvador - obrigado por tudo. Aqui, pegue alguns doces!",
  str_voice_1502281_30 = "Hum, isso é bastante bom.",
  str_voice_1502281_31 = "O selo na minha mão direita...",
  str_voice_1502281_32 = "\"Selo da Noite Eterna\", empreste-me seu poder...",
  str_voice_1502281_33 = "\"Uivo da Noite Eterna\" - Revele sua origem!",
  str_voice_1502281_34 = "Preciso intervir?",
  str_voice_1502281_35 = "O pote de doces está quase cheio!",
  str_voice_1502281_36 = "Envie-lhes um pequeno presente?",
  str_voice_1502281_37 = "Dê uma mordida no pêssego!",
  str_voice_1502281_38 = "Super doce!",
  str_voice_1502281_39 = "Doce como mel!",
  str_voice_1502281_40 = "Doce como torta!",
  str_voice_1502281_41 = "O Esquadrão Guerreiro, para a batalha!",
  str_voice_1502281_42 = "O seu destino de perder para mim me fará destinado a perder para alguém mais forte!",
  str_voice_1502281_43 = "Mas... é apenas um teste do destino...",
  str_voice_1502281_44 = "Para onde a história do nosso herói nos levará a seguir?",
  str_voice_1502281_45 = "Obrigado, quer um doce?",
  str_voice_1502281_46 = "Você sabia que eu precisava disso?",
  str_voice_1502281_47 = "Somos todos aliados do esquadrão agora - não há necessidade de ser tão formal!",
  str_voice_1502281_48 = "Você também foi guiado pelo destino, celestita.",
  str_voice_1502281_49 = "Desde que me lembro, Roy cuidou de mim. Para mim, ele é como um chefe de aldeia para o guerreiro!",
  str_voice_1502281_50 = "Hmph, não quero me gabar, mas sou bastante bom em dirigir. Na primeira vez que peguei a estrada, até derrubei três Eclipsitas!",
  str_voice_1502281_51 = "Eles sempre dizem que aquela bruxa... quero dizer, Azure, é uma corredora incrível, mas eu também já ganhei campeonatos!",
  str_voice_1502281_52 = "Alchemy Stars!",
  str_voice_1502281_53 = "Ei!",
  str_voice_1502281_54 = "Bom dia! Ufa!",
  str_voice_1502281_55 = "Já meio-dia?",
  str_voice_1502281_56 = "Huff... Sonolenta.",
  str_voice_1502281_57 = "Feliz Ano Novo! Você tem alguma resolução de Ano Novo? Vou contar tudo para o mestre do destino!",
  str_voice_1500924_1 = "Eu sei que eu fico bem com isso, mas você realmente não precisa me olhar assim. Hã? Você também não precisa me dar as costas! Você, você deveria... se virar...",
  str_voice_1500924_2 = "Por que eu sempre carrego a Pedra de Caça comigo? Não é óbvio? A Pedra de Caça é a peça de resistência de todo o meu traje!",
  str_voice_1500924_3 = "Tosse, tosse... O-ho-ho! Agora isso é o tipo de negócio que eu poderia apoiar! Confie em mim - seus associados de negócios não iriam querer perder o meu investimento! Hein? Quando você chegou aqui?! Eu não disse nada agora, você deve ter ouvido coisas!",
  str_voice_1500924_10 = "Por que você está me ignorando? Me diga, você fez algo que vai me deixar bravo, e agora está tentando me evitar? Huh? Você está apenas ocupado com o trabalho? Então... Eu acho que você simplesmente não tem um momento para poupar, certo?",
  str_voice_1500924_11 = "Hmph, já que você me convidou tão gentilmente, acho que não tenho problema em ajudá-lo. Apenas me diga qual tarefa difícil você precisa que eu cuide para você?",
  str_voice_1500924_12 = "Eu quero me livrar da Pedra de Caça? A Pedra de Caça é uma coisinha tão teimosa, se eu não cuidar dela, quem vai?",
  str_voice_1500924_13 = "\"Se você quer fazer negócios com pessoas lá fora, primeiro você precisa aprender a se vestir decentemente...\" Esta é, inegavelmente, uma regra de negócios importante. Você nunca ouviu isso antes? Bem, agora você ouviu.",
  str_voice_1500924_14 = "Não pense que está se escondendo tão bem - eu já notei você. Você foi quem me ajudou a sair daquele sonho. Mas não fique muito convencido... bem, suponho que você não pode evitar de se sentir um pouco satisfeito consigo mesmo!",
  str_voice_1500924_16 = "Se preparando para ir, hein? Ainda não? De jeito nenhum. Tudo bem, vou esperar por você.",
  str_voice_1500924_17 = "Bom dia. Gostaria de confirmar algo... Não tinha cenouras no café da manhã de hoje, tinha?",
  str_voice_1500924_18 = "Tantos convites para jantar... Por que você não vai a nenhum deles? Huh...? Você quer que eu te leve?",
  str_voice_1500924_19 = "O mundo não vai desabar se você quebrar algumas regras aqui e ali, mas você realmente deveria descansar um pouco.",
  str_voice_1500924_35 = "Você ainda não começou?",
  str_voice_1500924_36 = "O que você achou?",
  str_voice_1500924_37 = "Prove meus belos espinhos!",
  str_voice_1500924_38 = "Não lute. Isso vai doer ainda mais.",
  str_voice_1500924_39 = "Leve tudo!",
  str_voice_1500924_40 = "Você não pode escapar!",
  str_voice_1500924_44 = "Tenho gostado bastante daqui recentemente. Isso é exatamente o que Hunting Stone tem pensado, não eu!",
  str_voice_1500924_58 = "De agora em diante, vou viver uma vida honrada com a Pedra de Caça!",
  str_voice_1500924_59 = "Se você tiver um tempo, poderia me acompanhar novamente para Umbraton?",
  str_voice_1500924_60 = "Há algo que você gostaria que eu fizesse por você? Eu odeio dever favores tão grandes.",
  str_voice_1500924_61 = "Vou tentar considerar suas opiniões, mas comer cenouras é inegociável.",
  str_voice_1500924_62 = "Essa roupa se encaixa perfeitamente no que meu pai queria para mim, mas agora eu a uso por mim mesma.",
  str_voice_1500924_63 = "Esta cidade realmente era desconhecida antes? De fato, parece que cabe a mim assumir as rédeas.",
  str_voice_1500924_64 = "Contanto que ninguém esteja olhando, talvez... provar uma pedra do chão não seria fora de questão?",
  str_voice_1500924_65 = "Partir para a agressão sem dizer uma palavra... Absolutamente sem sentido. Agora eu só sinto tristeza pelo meu novo vestido.",
  str_voice_1500924_66 = "Se não fosse por aquele cheiro peculiar, essa floresta certamente seria deliciosa.",
  str_voice_1500924_67 = "Pedra de Caça, desta vez, é a minha vez de seguir seu rastro!",
  str_voice_1500924_68 = "Hmm? Devo ensinar-lhe como seguir as regras?",
  str_voice_1500924_69 = "Agora não é hora de descansar!",
  str_voice_1500924_70 = "Por que não está aqui?",
  str_voice_1500924_71 = "Tesouro descoberto!",
  str_voice_1602271_1 = "Relaxe, os Eclipsitas próximos não nos incomodarão. Veja, os Caçadores Águia Um e Dois estão enviando interferências lá em cima, e o Três também está em patrulha.",
  str_voice_1602271_2 = "Celestita Um... Ah, desculpe, PlayerName. Acho que ainda não me acostumei a chamar você pelo seu nome...",
  str_voice_1602271_3 = "Você quer que eu relaxe um pouco? É apenas um hábito. Se você não gosta, eu posso amenizar. Hmm, não era isso que você queria dizer?",
  str_voice_1602271_4 = "Se eu não fizer nenhum progresso, significa apenas que não tenho treinado o suficiente. Eu não sou como você, PlayerName— eu não nasci com esse poder.",
  str_voice_1602271_5 = "Quero me dedicar e continuar aprimorando os algoritmos dos Caçadores de Águia para que eles possam proporcionar maior segurança para minha equipe...",
  str_voice_1602271_6 = "Eu consegui, PlayerName! Ah, eu quero contar para os meus pais e minha tia agora mesmo. Não para restaurar a honra da nossa família, é só que eu quero compartilhar minha alegria com meus entes queridos primeiro.",
  str_voice_1602271_7 = "Há uma nova exposição no Museu Militar Illumina que eu quero arranjar tempo para ver. Então, quer vir? Não me importo que você venha junto.",
  str_voice_1602271_8 = "Eu tenho uma Insígnia de Sinergia extra que posso te dar. Sim, você precisa de duas metades para torná-la inteira. Onde está a outra metade? Eu a guardei.",
  str_voice_1602271_9 = "Sim, eu prometo a você. Pelo menos quando estou ao seu lado, não fico tão tenso.",
  str_voice_1602271_10 = "Você não vai me deixar ficar de guarda nem tirar uma folga... Você me chamou aqui porque quer me dizer algo?",
  str_voice_1602271_11 = "Ah, já que é um pedido seu, por que não?",
  str_voice_1602271_12 = "Claro que você não consegue encontrar drones como os Eagle Hunters em qualquer lugar de Illumina, eu mesmo os modifiquei. Não é estranho, eu me formei em engenharia mecânica na academia.",
  str_voice_1602271_13 = "Você às vezes me lembra minha irmãzinha. Hã? Eu não quis dizer nada de ruim com isso. Apesar de ser oito anos mais nova, ela já mostrou grande talento.",
  str_voice_1602271_14 = "O que eu faria se não houvesse guerra...? É um luxo para mim até mesmo imaginar isso, PlayerName. Eu só quero que estejamos seguros e bem agora.",
  str_voice_1602271_15 = "Tenho um bolo racionado aqui, mas não estou com muita fome... Você pode ficar com ele.",
  str_voice_1602271_16 = "Você parece ocupado também, hein? Nesse caso, você não pode ser o único a me dizer para descansar mais.",
  str_voice_1602271_17 = "Você acordou? Espero que meu treino matinal não tenha te incomodado. Tudo bem, você pode dormir um pouco mais.",
  str_voice_1602271_18 = "Hora do jantar? Obrigado, apenas me guarde uma mordida, não me importo com o sabor.",
  str_voice_1602271_19 = "Tudo bem. Estou acostumado a passar a noite toda em reconhecimentos. Mas você não deve se esgotar, vá descansar logo.",
  str_voice_1602271_20 = "Vamos para onde for necessário. Acredito na missão confiada à Federação Illumina. Ninguém mais pode fazer o que fazemos.",
  str_voice_1602271_21 = "Northland? Minha irmã adora os mitos e contos de fadas de Northland. Eu adoraria levá-la lá se tivesse a chance.",
  str_voice_1602271_22 = "Splendor Illumina!",
  str_voice_1602271_23 = "Um dia, nos livraremos de todas essas coisas escuras e sujas...",
  str_voice_1602271_24 = "Alguns dizem que eu me pareço um pouco com o Comandante Hiiro, mas sei que é apenas bajulação. Só espero não decepcionar o comandante.",
  str_voice_1602271_25 = "Shh, fale baixo... Como você sabia que eu queria acariciar a cauda do Comandante Philyshy?",
  str_voice_1602271_26 = "Quem é esse gatinho? May Eu... posso acariciar sua barriguinha macia?",
  str_voice_1602271_27 = "Embora seja apenas uma simulação de batalha, não quero perder um único ponto. Então não tente me parar. Eu posso continuar.",
  str_voice_1602271_28 = "Ver para crer, e eu vejo que o Colossus... não é adequado para um reconhecimento furtivo.",
  str_voice_1602271_29 = "Esquadrão Olho de Águia, Capitão—Caçador Águia Zero se reportando! Hã? É você... Celestita Um?",
  str_voice_1602271_30 = "O trabalho duro pode compensar muita coisa.",
  str_voice_1602271_31 = "Olhos afiados como os de uma águia...",
  str_voice_1602271_32 = "Ataque forte como as garras de um falcão...",
  str_voice_1602271_33 = "Mova-se rapidamente como um falcão à caça...",
  str_voice_1602271_34 = "Esquadrão Eagleeye, reúnam-se!",
  str_voice_1602271_35 = "O reconhecimento está feito!",
  str_voice_1602271_36 = "Aguardando ordens.",
  str_voice_1602271_37 = "É hora da Águia!",
  str_voice_1602271_38 = "Ataque de garra!",
  str_voice_1602271_39 = "Shiu! Cala a boca...",
  str_voice_1602271_40 = "Você não pode escapar agora.",
  str_voice_1602271_41 = "Beleza.",
  str_voice_1602271_42 = "Sim, isso faz parte do meu trabalho.",
  str_voice_1602271_43 = "Reagrupe e tente novamente!",
  str_voice_1602271_44 = "Meus Caçadores de Águia não deveriam assustar esses vaga-lumes, certo?",
  str_voice_1602271_45 = "Por mim?",
  str_voice_1602271_46 = "Tá bem. Valeu.",
  str_voice_1602271_47 = "Ah, você não precisava.",
  str_voice_1602271_48 = "Eu realmente gosto... Vou valorizar muito isso.",
  str_voice_1602271_49 = "Embora nascer em uma \"Família de Heróis\" em Gannon possa lhe trazer muita notoriedade, isso não lhe traz nenhum benefício real.",
  str_voice_1602271_50 = "As crianças talentosas foram escolhidas a dedo pelas principais academias e até comitês muito antes de mim. Mas eu não posso simplesmente me esconder no canto e permanecer inconformado.",
  str_voice_1602271_51 = "Em vez de estar abrigado em um laboratório seguro, prefiro lutar na linha de frente. É por isso que me juntei à 3ª Legião. Algum problema?",
  str_voice_1602271_52 = "Alchemy Stars.",
  str_voice_1602271_53 = "Senhor! Reportando.",
  str_voice_1602271_54 = "Bom dia.",
  str_voice_1602271_55 = "Boa tarde.",
  str_voice_1602271_56 = "Boa noite.",
  str_voice_1602271_57 = "Feliz Ano Novo. Eu? Meu único desejo é que minha irmãzinha seja despreocupada... e para você, desejo-lhe um ano novo feliz e seguro.",
  str_voice_1602291_1 = "Eu... Eu gosto de jogar jogos. Todo novo jogador começa no mesmo nível, e você sempre pode reiniciar se as coisas não saírem do seu jeito.",
  str_voice_1602291_2 = "Eu sei que não deveria usar meus pés para pegar coisas do chão... Mas minhas mãos geralmente estão muito ocupadas jogando.",
  str_voice_1602291_3 = "Minhas costas estão tão tensas... Se ao menos eu tivesse aceitado a mochila de massagem do Gronru antes. Espera, você quer me dar uma massagem? Er, não acho que seja necessário deitar, no entanto.",
  str_voice_1602291_4 = "Que tipo de jogos você mais gosta? Jogos de estratégia, jogos de luta, shooters, RPGs, ou... Eu sou mais para jogos clássicos.",
  str_voice_1602291_5 = "As pessoas do passado inventaram todos os tipos de videogames impressionantes, é difícil lembrar de todos eles. Deve ter sido tão gratificante ter tantas opções, mesmo que não houvesse tempo para jogar todos.",
  str_voice_1602291_6 = "Gronru uma vez mencionou jogos de realidade virtual. Se os jogos chegarem a esse ponto, tenho certeza de que serão usados para muitas coisas além dos jogos.",
  str_voice_1602291_7 = "Você quer que eu mostre como jogar este jogo? Bem, é meio difícil de explicar, então vamos começar logo, e eu vou te ensinar enquanto jogamos.",
  str_voice_1602291_8 = "*bocejos* Estou tentando muito me ajustar ao seu relógio biológico... Assim, podemos ter mais sobreposição durante nossos ciclos de vigília, certo?",
  str_voice_1602291_9 = "Com você como meu travesseiro, aposto que eu poderia dormir bem até mesmo à noite!",
  str_voice_1602291_10 = "Ei - Estou completamente longe do meu jogo agora! Se você já quis me derrotar, agora é sua chance...",
  str_voice_1602291_11 = "Está um pouco claro demais aqui, não acha? Ah, tudo bem... Vou manter as luzes acesas, para não forçar meus olhos.",
  str_voice_1602291_12 = "Administrar uma loja é difícil... Mas ainda bem que não há muitos jogadores em Astra. Eu deveria conseguir me aposentar bem cedo.",
  str_voice_1602291_13 = "Estou bem com jogos, bem com competições... mas subir ao palco para receber meus prêmios? Absolutamente não!",
  str_voice_1602291_14 = "Alguns jogos são mais divertidos quando você os joga com os outros. Essa é uma das razões pelas quais estou sempre no fliperama.",
  str_voice_1602291_15 = "Eu sabia que você era o tipo que usa seu aniversário real para seus personagens no jogo... Feliz aniversário.",
  str_voice_1602291_16 = "*bocejos* Ah, é você... ngh. 'tá bom, eu vou voltar a dormir quando você sair.",
  str_voice_1602291_17 = "Hmm? Surpreso em me ver acordado tão cedo pela manhã? Talvez seja porque... Eu nunca fui dormir.",
  str_voice_1602291_18 = "O café da manhã ainda não está pronto? Mas eu já estou acordado há um tempo.",
  str_voice_1602291_19 = "... Tá bom, vá dormir um pouco então. Precisa que eu te acorde de manhã?",
  str_voice_1602291_20 = "Umbraton é perfeito para pessoas como eu, já que Lumopolis bloqueia a maior parte do sol.",
  str_voice_1602291_21 = "A Federação Illumina parece estar guardando muitos jogos antigos como parte de sua coleção de artefatos antigos... Mas como eu supostamente conseguiria colocar as mãos nesses?",
  str_voice_1602291_22 = "A sombra tá observando você.",
  str_voice_1602291_23 = "Se ao menos lutar contra os Eclipsitas fosse como Tetrablox, então eu poderia juntá-los em linhas e eliminá-los com o bloco certo.",
  str_voice_1602291_24 = "Eu realmente não sou de interações sociais. Só sou falante quando converso sobre jogos com Gronru.",
  str_voice_1602291_25 = "Quero aprender algumas técnicas com Odi, para que eu possa desenterrar e consertar consoles de jogos antigos por mim mesmo.",
  str_voice_1602291_26 = "Eu poderia sobreviver jogando jogos pelo resto da minha vida. Se eu pudesse escolher apenas um jogo para jogar, teria que ser Tetrablox.",
  str_voice_1602291_27 = "Ruas lotadas em plena luz do dia... Urgh, isso me deixa tonto.",
  str_voice_1602291_28 = "Gostaria de poder ficar na sala de lazer e jogar o tempo todo, mas tem muita gente lá...",
  str_voice_1602291_29 = "Um ponto de exclamação apareceu! Carregando missão... Olá, meu nome é Batia, e eu sou a proprietária do Arcade Hidden Fangs em Umbraton. Bem-vindo ao mundo dos jogos!",
  str_voice_1602291_30 = "Suba de nível!",
  str_voice_1602291_31 = "Ascensão completa!",
  str_voice_1602291_32 = "Hora de encontrar um palco para testar meus novos poderes.",
  str_voice_1602291_33 = "Agora eu posso limpar ainda mais fases com você.",
  str_voice_1602291_34 = "Eu, contra os Eclipsitas? Sério?",
  str_voice_1602291_35 = "Isso deve ser pilhas suficientes...",
  str_voice_1602291_36 = "Hora de limpar o tabuleiro!",
  str_voice_1602291_37 = "Encaixa como uma luva.",
  str_voice_1602291_38 = "Não deixe espaços vazios.",
  str_voice_1602291_39 = "Potência de fogo total!",
  str_voice_1602291_40 = "Combo!",
  str_voice_1602291_41 = "Início do jogo.",
  str_voice_1602291_42 = "Ufa, palco limpo.",
  str_voice_1602291_43 = "Vou apenas reiniciar e tentar de novo.",
  str_voice_1602291_44 = "Algum jogo novo na sala de lazer? ...Vou verificar mais tarde esta noite.",
  str_voice_1602291_45 = "Tire seu tempo e escolha um presente adequado.",
  str_voice_1602291_46 = "Afinidade aumentou. Ótima escolha!",
  str_voice_1602291_47 = "Bandeira avistada...",
  str_voice_1602291_48 = "Parece que você encontrou a estratégia perfeita.",
  str_voice_1602291_49 = "Como um demi-humano morcego, eu realmente não gosto do sol, e meus braços e pernas são muito curtos para o trabalho normal... Basicamente, eu nasci naturalmente inútil. Eu acho?",
  str_voice_1602291_50 = "Graças aos videogames, conheci Gronru. Fiquei tão chocado quando ela elogiou minha intuição e velocidade de reação... Talvez eu não seja apenas um desajeitado afinal de contas?",
  str_voice_1602291_51 = "Graças a Gronru e alguns outros jogadores, desisti da minha vida NEET e me dediquei a administrar este fliperama. Meus clientes também se mostraram pessoas muito agradáveis.",
  str_voice_1602291_52 = "Boas-vindas a Alchemy Stars.",
  str_voice_1602291_53 = "Olá?",
  str_voice_1602291_54 = "Boa noite. *boceja*",
  str_voice_1602291_55 = "Onde está o baú...",
  str_voice_1602291_56 = "Estou de pé. Está tão quieto.",
  str_voice_1602291_57 = "Feliz Ano Novo! Não seja como eu e passe o Ano Novo Eve jogando... embora eu estivesse apenas matando tempo enquanto esperava por você!",
  str_voice_1601533_1 = "A luz do sol não é uma visão comum na cidade de Gannon. Trabalho duro para promover mudanças ambientais, defender uma vida saudável e encorajar todos a esperar pelo nascer do sol por apenas um motivo... Para que não esqueçamos de onde começamos.",
  str_voice_1601533_2 = "É hora do ensaio de dança... O quê? É uma questão de etiqueta, então eu tenho que estudar isso. Admitidamente, é bastante desafiador. Até mesmo Wrath luta para me acompanhar.",
  str_voice_1601533_3 = "Hmm? Isso não é exatamente um traje adequado para uma briga, mas... heh, se pode o que se quer.",
  str_voice_1601533_10 = "Desculpe pela espera. Finalmente terminei a agenda do dia. Oi. Você... está dormindo? Ha, aproveite essa paz enquanto dura.",
  str_voice_1601533_11 = "Tudo bem, dê espaço... Eu estou no comando agora!",
  str_voice_1601533_12 = "Algum problema? Você pode confiar em mim. Hah, as reclamações que eu ouvi em Illumina, você não acreditaria. E amigos, bem, eles devem compartilhar seus sentimentos uns com os outros, não é?",
  str_voice_1601533_13 = "Relaxe. Você nunca vai agradar a todos, então mantenha suas falhas em mente e tente progredir amanhã. Vá com calma! Você ainda tem muitos amanhãs pela frente.",
  str_voice_1601533_14 = "Os tempos mudam como a maré, e a Illumina está cavalgando as ondas. Não se preocupe, vou enfrentar a tempestade com todos os meus aliados a reboque.",
  str_voice_1601533_16 = "Mesmo que seja dia, lembre-se de descansar. Já ouviu o ditado, \"Todo trabalho e nenhuma diversão fazem do Navegador um garoto monótono\"?",
  str_voice_1601533_17 = "Bom dia. A propósito, esta mesa é tão desconfortável. Não é adequada para o tipo de longas horas que você está fazendo. Sugiro que você compre uma nova.",
  str_voice_1601533_18 = "Gosta de jantar em um banquete da cidade de Gannon? Não recue! Estamos falando de comida gourmet séria.",
  str_voice_1601533_19 = "A vista daqui é simplesmente celestial. Posso observar a longa noite, esperando pelo amanhecer.",
  str_voice_1601533_35 = "Me encara!",
  str_voice_1601533_36 = "Destrua todas as correntes!",
  str_voice_1601533_37 = "Enfrente sua aniquilação!",
  str_voice_1601533_38 = "Eu sou a iluminação de Illumina!",
  str_voice_1601533_39 = "É madrugada!",
  str_voice_1601533_40 = "Perfure a noite!",
  str_voice_1601533_44 = "Que base sublime. Vamos fazer uma pausa aqui e tomar banho na luz suave do céu.",
  str_voice_1601533_58 = "Você acordou cedo! Muito bom. Já considerou entrar para as forças especiais da Illumina?",
  str_voice_1601533_59 = "Bom dia! Você já deu uma olhada lá fora? O sol está brilhando, então não se esconda dentro de casa!",
  str_voice_1601533_60 = "Você já está acordado? Se quiser participar do banquete, é melhor começar a se preparar desde o amanhecer.",
  str_voice_1601533_61 = "Você tem se alimentado bem? Comida gourmet é tão difícil de encontrar.",
  str_voice_1601533_62 = "É quando o sol brilha mais forte. Espero que um dia Gannon também possa se banhar em sua glória.",
  str_voice_1601533_63 = "As pessoas geralmente parecem não gostar de discutir assuntos importantes neste horário do dia, mas eu realmente não me importo.",
  str_voice_1601533_64 = "Ao olhar para as estrelas, não se pode deixar de admirar a beleza do mundo.",
  str_voice_1601533_65 = "Descanse. Não preocupe as pessoas que se importam com você.",
  str_voice_1601533_66 = "É hora do banquete chegar ao fim. Vamos nos despedir desta noite inesquecível.",
  str_voice_1601533_67 = "Você acredita que o amanhecer um dia chegará a esta nossa terra?",
  str_voice_1601533_68 = "Devemos sempre nos esforçar para perseguir as estrelas, em vez de passar nossas vidas presos em um lugar.",
  str_voice_1601533_69 = "Para avançar, é preciso primeiro se libertar de todos os grilhões.",
  str_voice_1601533_70 = "Na maioria das vezes, escrevo minha própria lenda com a ponta da minha lança.",
  str_voice_1601533_71 = "A Illumina precisa de amigos - muitos deles.",
  str_voice_1500424_1 = "Você quer saber sobre o meu passado? Sente-se, eu tenho todo o tempo do mundo. Quando eu era jovem... até eu mesmo pensava que era um bastardo.",
  str_voice_1500424_2 = "Os Eclipsitas estão aqui! Os Eclipsitas estão aqui! Não me impeça. Alguém tem que tocar o clarim de vez em quando, ou a complacência os matará!",
  str_voice_1500424_3 = "Você já ouviu falar de balas afiadas? Nós as polimos ao máximo e garantimos que estejam usáveis ao mesmo tempo. Nós as guardamos apenas para as situações mais críticas...",
  str_voice_1500424_10 = "Cansado? Tudo bem. Ainda posso correr com você nas minhas costas. Então, vamos lá!",
  str_voice_1500424_11 = "Não consegue funcionar sem supervisão? Bem, sorte sua, supervisionar é a minha especialidade!",
  str_voice_1500424_12 = "Sempre acreditei que armas de fogo são mais poderosas do que espadas. Então, por que eu uso espadas? É uma longa história. Digamos apenas que o Oficial Pango gastou muito esforço me ensinando a arte da espada.",
  str_voice_1500424_13 = "Provavelmente não é meu lugar dizer isso, mas você deve valorizar aqueles ao seu redor. Não deixe aqueles que te ajudaram ir longe demais. Mantenha-os por perto, pois esses são seus camaradas.",
  str_voice_1500424_14 = "Por que eu te trato de maneira especial? Eu reconheço um herói quando vejo um. Não me importo de lutar por você quando as coisas ficam difíceis.",
  str_voice_1500424_16 = "Você acha que eu posso pilotar a Colossus ou algo assim? Ah, você não acha? Então o que você está esperando? Leve-nos aos Eclipsitas antes que minha paciência acabe!",
  str_voice_1500424_17 = "Entre na fila, seu preguiçoso!",
  str_voice_1500424_18 = "Costumávamos todos correr para o refeitório a esta hora. Se enrolássemos como você, teríamos morrido de fome.",
  str_voice_1500424_19 = "O sono suficiente garante um soldado em funcionamento. Vá para a cama. Eu vou ficar de guarda.",
  str_voice_1500424_35 = "Minha lâmina está desembainhada!",
  str_voice_1500424_36 = "Sem compromisso!",
  str_voice_1500424_37 = "Concha de aço!",
  str_voice_1500424_38 = "Liga afiada redonda!",
  str_voice_1500424_39 = "Oblitere-os!",
  str_voice_1500424_40 = "Disparar à vontade!",
  str_voice_1500424_44 = "Cansado? Quer se divertir?",
  str_voice_1500424_58 = "A 2ª Legião nunca recua!",
  str_voice_1500424_59 = "Seguir ordens é o meu trabalho. Pena que eu sou do tipo rebelde.",
  str_voice_1500424_60 = "Continue carregando! Não vamos parar até que todos os Eclipsitas sejam exterminados!",
  str_voice_1500424_61 = "Vamos fazer uma simulação militar.",
  str_voice_1500424_62 = "Todas as meninas adolescentes são monstros.",
  str_voice_1500424_63 = "Mostre a eles do que você é capaz!",
  str_voice_1500424_64 = "Cochilei acidentalmente. Ainda bem que ninguém me viu.",
  str_voice_1500424_65 = "Eu posso ir mais rápido. Barton, você consegue!",
  str_voice_1500424_66 = "Ah, interessante.",
  str_voice_1500424_67 = "Eu não esperava que aquele velhote fosse fotogênico.",
  str_voice_1500424_68 = "Siga-me e mostre a eles como os Illuminans fazem isso!",
  str_voice_1500424_69 = "Droga, você pegou o holofote dessa vez...",
  str_voice_1500424_70 = "Reinhardt mudou. Todos eles mudaram... Ficou muito complicado para eu entender...",
  str_voice_1500424_71 = "Isso não é nada. Eu nem usei as rodadas afiadas ainda! Eu não posso concordar com isso...",
  str_voice_1601553_1 = "Você quer saber sobre o meu passado? Sente-se, eu tenho todo o tempo do mundo. Quando eu era jovem... até eu mesmo pensava que era um bastardo.",
  str_voice_1601553_2 = "Os Eclipsitas estão aqui! Os Eclipsitas estão aqui! Não me impeça. Alguém tem que tocar o clarim de vez em quando, ou a complacência os matará!",
  str_voice_1601553_3 = "Você já ouviu falar de balas afiadas? Nós as polimos ao máximo e garantimos que estejam usáveis ao mesmo tempo. Nós as guardamos apenas para as situações mais críticas...",
  str_voice_1601553_10 = "Cansado? Tudo bem. Ainda posso correr com você nas minhas costas. Então, vamos lá!",
  str_voice_1601553_11 = "Não consegue funcionar sem supervisão? Bem, sorte sua, supervisionar é a minha especialidade!",
  str_voice_1601553_12 = "Sempre acreditei que armas de fogo são mais poderosas do que espadas. Então, por que eu uso espadas? É uma longa história. Digamos apenas que o Oficial Pango gastou muito esforço me ensinando a arte da espada.",
  str_voice_1601553_13 = "Provavelmente não é meu lugar dizer isso, mas você deve valorizar aqueles ao seu redor. Não deixe aqueles que te ajudaram ir longe demais. Mantenha-os por perto, pois esses são seus camaradas.",
  str_voice_1601553_14 = "Por que eu te trato de maneira especial? Eu reconheço um herói quando vejo um. Não me importo de lutar por você quando as coisas ficam difíceis.",
  str_voice_1601553_16 = "Você acha que eu posso pilotar a Colossus ou algo assim? Ah, você não acha? Então o que você está esperando? Leve-nos aos Eclipsitas antes que minha paciência acabe!",
  str_voice_1601553_17 = "Entre na fila, seu preguiçoso!",
  str_voice_1601553_18 = "Costumávamos todos correr para o refeitório a esta hora. Se enrolássemos como você, teríamos morrido de fome.",
  str_voice_1601553_19 = "O sono suficiente garante um soldado em funcionamento. Vá para a cama. Eu vou ficar de guarda.",
  str_voice_1601553_35 = "Minha lâmina está desembainhada!",
  str_voice_1601553_36 = "Sem compromisso!",
  str_voice_1601553_37 = "Concha de aço!",
  str_voice_1601553_38 = "Liga afiada redonda!",
  str_voice_1601553_39 = "Oblitere-os!",
  str_voice_1601553_40 = "Disparar à vontade!",
  str_voice_1601553_44 = "Cansado? Quer se divertir?",
  str_voice_1601553_58 = "A 2ª Legião nunca recua!",
  str_voice_1601553_59 = "Seguir ordens é o meu trabalho. Pena que eu sou do tipo rebelde.",
  str_voice_1601553_60 = "Continue carregando! Não vamos parar até que todos os Eclipsitas sejam exterminados!",
  str_voice_1601553_61 = "Vamos fazer uma simulação militar.",
  str_voice_1601553_62 = "Todas as meninas adolescentes são monstros.",
  str_voice_1601553_63 = "Mostre a eles do que você é capaz!",
  str_voice_1601553_64 = "Cochilei acidentalmente. Ainda bem que ninguém me viu.",
  str_voice_1601553_65 = "Eu posso ir mais rápido. Barton, você consegue!",
  str_voice_1601553_66 = "Ah, interessante.",
  str_voice_1601553_67 = "Eu não esperava que aquele velhote fosse fotogênico.",
  str_voice_1601553_68 = "Siga-me e mostre a eles como os Illuminans fazem isso!",
  str_voice_1601553_69 = "Droga, você pegou o holofote dessa vez...",
  str_voice_1601553_70 = "Reinhardt mudou. Todos eles mudaram... Ficou muito complicado para eu entender...",
  str_voice_1601553_71 = "Isso não é nada. Eu nem usei as rodadas afiadas ainda! Eu não posso concordar com isso...",
  str_voice_1602301_1 = "O néctar da vida complementa a sustentação. Ele proporciona aos seus bebedores um sono sem sonhos e impede aqueles que sofrem de se afundarem em autopiedade. Gostaria de experimentar?",
  str_voice_1602301_2 = "Não é nada divertido ficar nas sombras assistindo Aurorians e Eclipsitas se matando, mas às vezes essa é a lição da Verdade. Por que, você sente falta disso?",
  str_voice_1602301_3 = "Aqueles que não me entendem tendem a afirmar que minhas palavras são profundas, ou até mesmo duvidosas. Eles me evitam, mas me espionam... Tenho certeza que você sabe como isso se sente.",
  str_voice_1602301_4 = "Você já ouviu a frase, \"O corpo é a prisão da alma de um Aurorian\"? ...Hehe. Sua carranca diz tudo.",
  str_voice_1602301_5 = "Alguns acreditam em transcender a si mesmos para obter um poder maior que o mundo, mas o \"eu\" não é tão facilmente transcendido, e abandonar a si mesmo desvia do que a Verdade ordena.",
  str_voice_1602301_6 = "Ódio e guerra são apenas medidas extremas para os humildes ganharem poder. Eles não sabem onde reside o Senhor da Verdade.",
  str_voice_1602301_7 = "Você reclamaria do destino quando está de mau humor? Por que não mudar sua mentalidade para acreditar que é destino? Então revele a verdade por trás disso com alegria?",
  str_voice_1602301_8 = "Eu frequentemente expliquei a eles que desenvolver sua percepção não é para entender o mundo, pois a Verdade permeia muitas dimensões. Uma verdade colhida ao compreender o mundo não é a Verdade.",
  str_voice_1602301_9 = "A suprema verdade se esconde nas profundezas extremas da emoção. Os Aurorians próximos a você já lhe mostraram a verdade deles. Aguardo ansiosamente minhas jornadas com você.",
  str_voice_1602301_10 = "Você tem me encarado. Não está acostumado a me ver assim? Mesmo de costas para mim, vou considerar suas expressões como um elogio.",
  str_voice_1602301_11 = "Apesar da Nação da Verdade ter sofrido um colapso antes, Ele ainda é Ele. Ele está dentro de cada criatura viva para mostrar a Verdade. Mesmo que Ele tenha encontrado um lugar para vir, Ele mudou de ideia quando você nasceu.",
  str_voice_1602301_12 = "A única rota para se aproximar da Verdade é através da aquisição de conhecimento. Isso requer que um indivíduo integre as informações adquiridas com a iluminação interior. Entidades diferentes adquirem conhecimentos diferentes, portanto, a Verdade assume formas diferentes.",
  str_voice_1602301_13 = "Existe um mundo em cada auroriano. Todos estão em seu próprio mundo no momento, e o Senhor da Verdade está entre eles, governando toda a terra.",
  str_voice_1602301_14 = "O verdadeiro sono não pertence aos falecidos, pois na Nação da Verdade, até mesmo a morte se dissipará. Eu observei todos e me tornei indiferente à natureza efêmera das vidas individuais.",
  str_voice_1602301_15 = "A idade é a comemoração mais inútil. Mas se você quiser, eu realmente desejo a você um feliz aniversário.",
  str_voice_1602301_16 = "Você precisa da minha ajuda? Só custa um pequeno preço... Ah, sua expressão é interessante como sempre.",
  str_voice_1602301_17 = "Guarda-chuva? Não, não preciso de um. Meu cabelo e pele apenas brilham mais sob o sol.",
  str_voice_1602301_18 = "É uma lua bonita esta noite, mas ainda empalidece em comparação com a lua de sangue na Cidade Varaki.",
  str_voice_1602301_19 = "As Escrituras profetizaram sua chegada, mas muito mais tarde.",
  str_voice_1602301_20 = "O Senhor da Verdade veio para testemunhar a Verdade, e todos aqueles que aderem à Verdade testemunharão milagres.",
  str_voice_1602301_21 = "Oprimir os crentes, mas querer aprender A Verdade com eles ao mesmo tempo é a maior farsa para A Verdade.",
  str_voice_1602301_22 = "Que a Verdade te abençoe.",
  str_voice_1602301_23 = "Eclipsitas não são puramente maléficos, assim como os Aurorianos não são puramente benevolentes. Eles se perdem porque estão sem a orientação do Senhor da Verdade.",
  str_voice_1602301_24 = "Ouça, persevera, sinta tanto amor quanto ódio pelo mundo, então despedace o passado e reconstrua-se... Foi assim que ele se aproximou da Verdade, acredito eu.",
  str_voice_1602301_25 = "Depois de ver o poder de Nails, eu sabia que ele tinha o potencial para ser um apóstolo. Agora, chegou a hora dele.",
  str_voice_1602301_26 = "Meus hobbies? Por que você não usa seu poder para melhor <color=#FEF49B>ligação</color> comigo?",
  str_voice_1602301_27 = "Opressão, vida eterna, reclamações e delírios... Como você pode ver, não sou eu quem questiona ou detesta eles.",
  str_voice_1602301_28 = "Quanto a se Ele está na Colossus... Minha resposta seria negativa no passado.",
  str_voice_1602301_29 = "Já que você veio aqui por vontade própria, embarque na Verdade. Para onde ela vai, depende de mim. Para alguém que buscou a Verdade frequentemente, você deveria estar curioso sobre mim, certo?",
  str_voice_1602301_30 = "Que poder misterioso e incrível.",
  str_voice_1602301_31 = "Eu vou transcender a vida e a morte!",
  str_voice_1602301_32 = "Vou transcender o tempo e o espaço!",
  str_voice_1602301_33 = "A eternidade está aqui!",
  str_voice_1602301_34 = "Você gostaria de ver algo diferente?",
  str_voice_1602301_35 = "Recite os mantras comigo.",
  str_voice_1602301_36 = "Isso é o que foi imbuído no meu sangue.",
  str_voice_1602301_37 = "A Calamidade foi lançada!",
  str_voice_1602301_38 = "Levante, espírito de sangue!",
  str_voice_1602301_39 = "Ouça A Verdade!",
  str_voice_1602301_40 = "Eu sou A Verdade!",
  str_voice_1602301_41 = "Aguardando a chegada de Deus.",
  str_voice_1602301_42 = "Eu te assustei?",
  str_voice_1602301_43 = "Grave a Verdade no meu corpo.",
  str_voice_1602301_44 = "Sim, faremos uma congregação para a Verdadeira Ordem aqui.",
  str_voice_1602301_45 = "Gostaria de ouvir a Verdade comigo?",
  str_voice_1602301_46 = "Ele tem muitos crentes, mas apenas um deles é um Celestita...",
  str_voice_1602301_47 = "Não se mexa... Ouviu isso? Está dentro.",
  str_voice_1602301_48 = "Em comparação com os tomos antigos de origens desconhecidas, eu preferi mais o seu presente.",
  str_voice_1602301_49 = "Eu posso entender por que os patriarcas evitaram a linhagem Varaki, assim como o desejo dos meus pais de terminar suas vidas. É por isso que eu estava apático a tudo ao meu redor quando experimentei a ascensão.",
  str_voice_1602301_50 = "Isso está correto, eu fugi daquela cidade da lua de sangue, não porque eu tinha o poder de me mover à luz do dia, mas porque eu queria experimentar algo diferente.",
  str_voice_1602301_51 = "Há muito tempo, ouvi a revelação do Senhor da Verdade no túmulo dos meus antepassados, com muitos de seus delírios também sobrecarregando minha mente. A dor é incidental, mas se aproximar da Verdade é essencial.",
  str_voice_1602301_52 = "Alchemy Stars.",
  str_voice_1602301_53 = "Bem, eles estão certos.",
  str_voice_1602301_54 = "O dia amanhece antes que você perceba...",
  str_voice_1602301_55 = "Hora de ler.",
  str_voice_1602301_56 = "Entregando agora?",
  str_voice_1602301_57 = "A True Order aguarda sua visita no ano novo.",
  str_voice_1502321_1 = "Meu mentor uma vez perguntou pelo que eu havia me arrependido todos esses anos. Eu respondi: \"Tudo—Nascer. Existir. Falar. Pensar...\" Esta é a primeira vez que alguém me ouve por muito tempo sem ir embora.",
  str_voice_1502321_2 = "Não ouso esperar pela redenção... mas quando o Sangue Raro se condensou e tomou forma, e os discípulos elogiaram minha santidade, eu pensei brevemente em ser \"salvo\".",
  str_voice_1502321_3 = "\"Onde você perde, aqui você ganha. Onde você se redime, aqui você é abençoado.\" Em outras palavras... Não estou fazendo nada nojento e chato, e não sou um monstro abandonado...",
  str_voice_1502321_4 = "A dor que vejo não é real, pois mesmo quando a ferida cicatriza, ainda estou preso no clima de perda. Mas não se preocupe comigo, ocasionalmente estou feliz agora.",
  str_voice_1502321_5 = "Você quer dizer o \"Nails de Piedade\"? Ah... É definitivamente diferente. Mais afiado, mais elegante, e eu posso confessar em mais ocasiões. Que tal... Hã? Você quer dizer juntos?",
  str_voice_1502321_6 = "Justo quando eu estava prestes a sangrar até a morte, fiquei brevemente hipotérmico... Eu me disse que finalmente estava caindo no sono que tanto ansiava, mas meu mentor me envolveu em sua santidade...",
  str_voice_1502321_7 = "Discípulos lá dizem que o Senhor da Verdade é o deus que semeia a noite e faz toda a dor desaparecer durante o dia. Estou tentando pensar nisso assim, como uma espécie de confissão...",
  str_voice_1502321_8 = "Depois de entrar para a True Order, rapidamente encontrei um motivo para minha dor e culpa. Mas a raiz da confissão é o nojo... e a raiz do nojo... você não quer saber...",
  str_voice_1502321_9 = "O Sangue Raro é frio e cortante, mas o Sangue Sagrado é como o fogo ardente do renascimento. Ele me queima, me guia, me permite salvar os outros enquanto me salvo.",
  str_voice_1502321_10 = "Oh... Eu estava tão encantado com essa roupa que esqueci que você estava lá, desculpe. Então, por favor, comece sua confissão. Eu vou ouvir atentamente.",
  str_voice_1502321_11 = "Eu sabia que o dia chegaria quando eu te contaria sobre meu passado pecaminoso. Bem, vou olhar nos seus olhos. Estou pronto...",
  str_voice_1502321_12 = "Ah... Essas são as feridas que aqueles bons discípulos enfaixaram para mim. Eles não me desprezaram, mas foram gratos pelo meu serviço... Sim! Eu vou me adaptar a isso com gratidão!",
  str_voice_1502321_13 = "Eu sou inocente aos olhos da Verdade! Ah... Apesar dos meus melhores esforços, você ainda pode me ouvir me culpando, não é?",
  str_voice_1502321_14 = "O que eu deveria confessar? Seu tempo desperdiçado? Seu dinheiro desperdiçado? Seu... Desculpe. Eu não deveria ter falado tanto...",
  str_voice_1502321_15 = "Deus te abençoe. Espero confessar com você todos os anos... não, todos os dias!",
  str_voice_1502321_16 = "Você poderia ajudar a verificar se a ferida nas minhas costas está curada? Eu acidentalmente fui um pouco fundo demais da última vez...",
  str_voice_1502321_17 = "É cedo... você é um discípulo da Verdade mais devoto do que eu.",
  str_voice_1502321_18 = "Agora mesmo? Claro. Mostrar as próprias feridas para aqueles que buscam a Verdade é o que os santos devem fazer.",
  str_voice_1502321_19 = "O sono também te evade por causa dos pecados em seu coração? Felizmente, tenho muito a confessar para você...",
  str_voice_1502321_20 = "Eles não tiveram pena ou me rejeitaram, mas ao invés disso, ansiavam ver o Senhor da Verdade descer sobre mim.",
  str_voice_1502321_21 = "De qualquer forma, eu não pertenço mais lá. Não é assim que um santo deve se comportar. Essas são minhas últimas palavras para eles...",
  str_voice_1502321_22 = "Que a Verdade te abençoe!",
  str_voice_1502321_23 = "Eclipsitas também sentem dor às vezes?",
  str_voice_1502321_24 = "É apenas porque a Senhora Victoria me aceitou e me guiou que eu estava qualificado para me tornar um santo do senhor.",
  str_voice_1502321_25 = "Ele me lê... buscando a raiz do pecado em minhas palavras de confissão... minha professora da Verdade, minha mentora para a vida!",
  str_voice_1502321_26 = "Enquanto eu estava morrendo, ouvi a voz do senhor... mesmo que tenha sido apenas uma ilusão, vou procurá-la novamente.",
  str_voice_1502321_27 = "Só recentemente percebi que me odeio. Ah... obrigado. Vou conseguir me aceitar um dia.",
  str_voice_1502321_28 = "Perdoe-me, mas o confessionário não está pronto ainda?",
  str_voice_1502321_29 = "Muitas pessoas viram a mudança em mim, mas você é o primeiro a perguntar o que eu vivenciei... Esta vestimenta sagrada é um testemunho do abraço do Senhor da Verdade.",
  str_voice_1502321_30 = "Senhor, perdoe-me mais uma vez...",
  str_voice_1502321_31 = "O que estou perdendo...?",
  str_voice_1502321_32 = "Sempre serei grato...",
  str_voice_1502321_33 = "O Senhor disse que eu sou inocente!",
  str_voice_1502321_34 = "Eu não devo sujar minhas roupas...",
  str_voice_1502321_35 = "O Sangue Sagrado está prestes a se condensar e tomar forma...",
  str_voice_1502321_36 = "Isso não é meu poder...",
  str_voice_1502321_37 = "Eu responderei pelos pecadores!",
  str_voice_1502321_38 = "Eu vou ouvir as confissões das vítimas!",
  str_voice_1502321_39 = "Sem dor...!",
  str_voice_1502321_40 = "Há muitos mais...!",
  str_voice_1502321_41 = "Vou sofrer por você...",
  str_voice_1502321_42 = "O senhor lavou meus pecados mais uma vez.",
  str_voice_1502321_43 = "Não sou digno de ser chamado de santo...",
  str_voice_1502321_44 = "Eu não estou mais sujo... certo?",
  str_voice_1502321_45 = "Receberei em nome do senhor...",
  str_voice_1502321_46 = "Será que eu realmente posso ficar com isso para mim...?",
  str_voice_1502321_47 = "Você merece mais do que eu.",
  str_voice_1502321_48 = "Eu deveria me dar algum crédito...",
  str_voice_1502321_49 = "Essa experiência me fez perceber que era superficial considerar apenas minha própria dor. O sangue manchado não vai desaparecer porque eu confesso, eu preciso fazer algo com ele...",
  str_voice_1502321_50 = "Às vezes, sinto-me feliz por estar vivo, mas apenas ocasionalmente... Mas quando penso no meu irmão segurando a espada do herdeiro com aquela expressão vazia, eu simplesmente...",
  str_voice_1502321_51 = "Tudo o que eu sabia era que a Verdadeira Ordem era um lugar para excêntricos e excluídos... Mas mais tarde descobri que são justamente esses estranhos que trazem razão para o mundo exterior.",
  str_voice_1502321_52 = "Alchemy Stars.",
  str_voice_1502321_53 = "Se possível...",
  str_voice_1502321_54 = "Um novo dia de confissão começa.",
  str_voice_1502321_55 = "Tenho mais uma coisa para dizer.",
  str_voice_1502321_56 = "Você está farto de mim...?",
  str_voice_1502321_57 = "Obrigado por não se cansar de mim durante o último ano.",
  str_voice_1602311_1 = "PlayerName, mantenha essa sua cabeça de melão para si mesmo, e nunca tente entrar na minha cabeça enquanto finge ser o Senhor da Verdade. Você não pode me enganar agora.",
  str_voice_1602311_2 = "Você é amigo de Victoria? Nesse caso, não me importo que você me chame de \"Tio\".",
  str_voice_1602311_3 = "Tem certeza de que é assim que você quer abordar isso? Desculpe, mas para mim, cuspir palavras sem pensar é o caminho dos bárbaros incivilizados.",
  str_voice_1602311_4 = "O caminho para a Verdade é muito menos complicado do que você pensa, PlayerName. Você só precisa acreditar no poder da sua crença.",
  str_voice_1602311_5 = "Toda alma neste mundo é profundamente abençoada pela Verdade. Ao oferecer nossa fé inabalável ao Senhor da Verdade, podemos escapar do tormento eterno.",
  str_voice_1602311_6 = "Um dia, você também vai deitar naquele rio. Então A Verdade, como a estrela que brilha mais forte na noite, vai te empalar, te despedaçar, te queimar, te reconstruir... até que você não seja mais você e se torne você novamente.",
  str_voice_1602311_7 = "Já disse muitas vezes para Nails não sair me anunciando como seu mentor. Veja, agora você também está aqui... Hã? Você não me quer como seu mentor? Por que, você não acha que sou bom o suficiente?",
  str_voice_1602311_8 = "Todos têm seu próprio caminho para a iluminação, e eu nunca interfiro. Mas não quero ver você se desviando muito do curso. Você deveria ser inteligente o suficiente para saber o que eu quero dizer.",
  str_voice_1602311_9 = "Concluí meu objetivo como membro da família Varaki. Agora, use sua cabeça de melão e descubra qual pobre coitado eu posso ajudar?",
  str_voice_1602311_10 = "Você é realmente tão quieto quanto um coelho? Isso realmente desperta minha curiosidade agora... Então você não tem nenhuma pergunta sobre A Verdade e a realidade do mundo para mim?",
  str_voice_1602311_11 = "Muito bem, vejo que você tem um quarto vazio pronto para mim. Não se preocupe, eu não vou reclamar por ser apertado.",
  str_voice_1602311_12 = "Ao contrário de você, não recebo muitas pessoas no meu castelo, mas se você vier sozinho, serei considerado e pelo menos providenciarei um caixão adequado para você.",
  str_voice_1602311_13 = "A verdade é onipresente. Na lama após uma tempestade, nas páginas amareladas de um livro, dentro de você e de mim... todos contêm vestígios da Verdade.",
  str_voice_1602311_14 = "Devorando tudo e matando todos, mas nunca pode ser preso. Você sabe quem é esse \"fugitivo\"? Muito poucos podem responder corretamente, mas talvez você seja uma exceção...",
  str_voice_1602311_15 = "Acredito que seja aniversário de alguém hoje. Por favor, diga a essa certa pessoa—Feliz Aniversário.",
  str_voice_1602311_16 = "Tenho razões para acreditar que até o Senhor da Verdade ficará perplexo com isso... O que diabos você está fazendo que está te mantendo tão ocupado?",
  str_voice_1602311_17 = "Vejo que alguém nunca viu um café da manhã delicioso antes. Não fique apenas sentado aí, a menos que prefira seus ensopados frios.",
  str_voice_1602311_18 = "Você finalmente decidiu se mostrar? Bem, ainda não é tarde demais. O dia está apenas começando a se desdobrar.",
  str_voice_1602311_19 = "O que está errado? Respire fundo, você não está fazendo sentido agora. Então, você está tentando me dizer que alguém te pregou peças no seu sonho?",
  str_voice_1602311_20 = "A atual Verdadeira Ordem embarcou firmemente em uma passagem abençoada pela Verdade.",
  str_voice_1602311_21 = "As ovelhas hereges que seguiam um falso deus estariam vivendo uma vida muito mais indesejável agora se não tivessem se apossado daquela cidade flutuante.",
  str_voice_1602311_22 = "Que a Verdade abençoe você.",
  str_voice_1602311_23 = "Como poderia o inimigo da Verdade ser meu amigo?",
  str_voice_1602311_24 = "Eu me pergunto se Victoria ainda me odeia como antes? Não, não meta o nariz onde não é chamado, PlayerName.",
  str_voice_1602311_25 = "Charon e seu pai têm um relacionamento tenso? Bem, isso não é novidade nenhuma.",
  str_voice_1602311_26 = "Perdoe-me, mas prefiro ficar sozinho. No entanto, se você for quieto como um coelho, não me importo de compartilhar espaços com você.",
  str_voice_1602311_27 = "Qualquer lugar com um público barulhento certamente estará cheio de enganos, traições e brigas... Prometa-me que você não vai chegar perto.",
  str_voice_1602311_28 = "Você é muito sortudo por possuir um castelo móvel. Também é óbvio que você se esforçou para a aparência dele.",
  str_voice_1602311_29 = "Além de orientar você sobre como combater as tentações e sussurros pecaminosos em sua vida, não há nada que eu possa ajudar. Mas mesmo assim, você ainda está disposto a se aproximar de mim, eu vejo.",
  str_voice_1602311_30 = "Ah, meu senhor...",
  str_voice_1602311_31 = "O esclarecimento é um processo eterno.",
  str_voice_1602311_32 = "A orientação está cada vez mais clara.",
  str_voice_1602311_33 = "Como se eu tivesse voltado ao rio...",
  str_voice_1602311_34 = "Deixe-me dar uma olhada.",
  str_voice_1602311_35 = "A lâmina está pronta.",
  str_voice_1602311_36 = "Você gosta de esperar?",
  str_voice_1602311_37 = "A luz da lua de sangue!",
  str_voice_1602311_38 = "Deixe a rosa florescer!",
  str_voice_1602311_39 = "Fluxo...",
  str_voice_1602311_40 = "Dormir...",
  str_voice_1602311_41 = "Eu vou ficar bem.",
  str_voice_1602311_42 = "Como eu disse, vai ficar tudo bem.",
  str_voice_1602311_43 = "Fique atrás de mim rapidamente!",
  str_voice_1602311_44 = "É aqui onde você viveu em reclusão por dezessete anos?",
  str_voice_1602311_45 = "Não é de admirar que todos quisessem vir.",
  str_voice_1602311_46 = "É especial, não é?",
  str_voice_1602311_47 = "Você é bom em agradar as pessoas.",
  str_voice_1602311_48 = "Você pode esperar pelo que pode receber em troca.",
  str_voice_1602311_49 = "Os Varakis têm uma história muito mais longa do que você imagina. Se estiver interessado, posso relatar a vida de cada antepassado para você... Isso é, se você estiver interessado.",
  str_voice_1602311_50 = "Achei que estava seguindo a Verdade naquela época, mas para os outros, eu estava apenas traindo meus irmãos.",
  str_voice_1602311_51 = "Tranquei-me em um forte em um precipício, apenas para encontrar contentamento e serenidade inesperados.",
  str_voice_1602311_52 = "Alchemy Stars.",
  str_voice_1602311_53 = "Alguém está procurando por mim?",
  str_voice_1602311_54 = "Está começando a ficar barulhento.",
  str_voice_1602311_55 = "Uma tarde preguiçosa...",
  str_voice_1602311_56 = "Vamos ver quem já está cochilando?",
  str_voice_1602311_57 = "Todos podem acolher um novo ano, assim como todos podem acolher o rio da Verdade.",
  str_voice_1602331_1 = "Obrigado por me receber a bordo do Colossus! Esta é a minha primeira vez vendo um dirigível assim; parece tão aventureiro!",
  str_voice_1602331_2 = "Há algo que eu possa fazer para te ajudar? Minha alquimia é perfeita para transformar materiais aparentemente comuns em itens úteis!",
  str_voice_1602331_3 = "Você recebeu um pedido de emprego interessante ou algo assim? Todos parecem tão animados!",
  str_voice_1602331_4 = "Os Vaga-lumes são tão fofos! Se ao menos eu pudesse usar a alquimia para criar esses pequenos ajudantes adoráveis!",
  str_voice_1602331_5 = "Astra tem todos os tipos de materiais úteis! Mal posso esperar para explorá-los para minha pesquisa!",
  str_voice_1602331_6 = "Vice diz \"alquimia\" é um termo antigo em seu mundo, usado para descrever uma prática mística incrível... Eu também espero aprender mais conhecimento e técnicas de alquimia no futuro.",
  str_voice_1602331_7 = "Você sabe como pescar? O que é isso? Você realmente ama pescar?! Ótimo, vou fazer para nós um par de varas de pescar!",
  str_voice_1602331_8 = "Conte-me sobre outra de suas aventuras! Estou morrendo de vontade de ouvir mais sobre elas!",
  str_voice_1602331_9 = "Obrigada, Navegador, por toda a sua ajuda durante nosso tempo na ilha e em seu Colosso... meus amigos e eu tivemos um verão inesquecível!",
  str_voice_1602331_10 = "Barril!",
  str_voice_1602331_11 = "Heehee, bem-vindo ao meu Atelier de classe mundial! Mesmo sendo apenas uma configuração temporária, já fiz muitos itens úteis para nós. Veja se há algo que você pode usar!",
  str_voice_1602331_12 = "Troquei materiais com alguns dos seus amigos da Rediesel Wrench agora mesmo. Eles trouxeram todos os tipos de coisas inesperadas, como lagartos secos e até cactos!",
  str_voice_1602331_13 = "Um lugar que eu gostaria de visitar? Bem, se eu tivesse a chance... Eu adoraria conhecer Lumópolis! Northland também parece uma ótima escolha... Ahh, eu não consigo me decidir!",
  str_voice_1602331_14 = "Tantas pessoas neste mundo também adoram explorar ruínas! Vice me contou sobre algumas de suas explorações anteriores; Sinto que poderíamos compartilhar histórias por horas!",
  str_voice_1602331_15 = "Feliz aniversário! Impressionante, não? Meus amigos e eu preparamos isso apenas para você, e eu usei alquimia para criar todos os itens necessários!",
  str_voice_1602331_16 = "Quero pesquisar este material... Mas onde posso encontrá-lo?",
  str_voice_1602331_17 = "Bom dia! Estou empolgado e pronto para ir a qualquer hora!",
  str_voice_1602331_18 = "O jantar estava delicioso, e eu também pude ouvir todos os tipos de histórias!",
  str_voice_1602331_19 = "Ufa... Obrigado por me ajudar a explorar materiais! Boa noite...",
  str_voice_1602331_20 = "Outra aventura de verão completamente nova para a minha vida ordinária!",
  str_voice_1602331_21 = "Está decidido! O próximo da minha lista é ver a aurora em Northland.",
  str_voice_1602331_22 = "Em sua forma mais simples, a alquimia é a exploração e síntese de diferentes materiais!",
  str_voice_1602331_23 = "Nenhum inimigo é perigoso demais para parar nossa aventura!",
  str_voice_1602331_24 = "A flauta de Klaudia é fenomenal; devemos deixá-la apresentar um concerto novamente algum dia!",
  str_voice_1602331_25 = "Será que a Patty está bem? Eu adoraria apresentá-la a alguns novos amigos!",
  str_voice_1602331_26 = "Como alquimista, meu maior desejo é adquirir ainda mais conhecimento e técnicas!",
  str_voice_1602331_27 = "Se alguém te maltratar, não há nada de errado em revidar!",
  str_voice_1602331_28 = "Voando pelo mundo a bordo de um enorme dirigível... É como algo saído de um sonho!",
  str_voice_1602331_29 = "Meu nome é Reisalin Stout, ou Ryza para abreviar! Sou uma alquimista viajante, e meus interesses incluem visitar diferentes mundos, explorar ruínas, ter aventuras de verão e voar a bordo desta Colossus!",
  str_voice_1602331_30 = "Ainda posso me tornar mais forte!",
  str_voice_1602331_31 = "Exploração concluída!",
  str_voice_1602331_32 = "Síntese bem sucedida!",
  str_voice_1602331_33 = "Tudo bem, acabou!",
  str_voice_1602331_34 = "Dê o primeiro passo e vá!",
  str_voice_1602331_35 = "Vou lutar a sério!",
  str_voice_1602331_36 = "Aqui vamos nós!",
  str_voice_1602331_37 = "Este é o meu movimento final!",
  str_voice_1602331_38 = "A vitória é nossa! Grande Carroça!",
  str_voice_1602331_39 = "Ataque—",
  str_voice_1602331_40 = "Contemple o poder da alquimia!",
  str_voice_1602331_41 = "Certo, vamos nos divertir!",
  str_voice_1602331_42 = "Sim! Conseguimos—!",
  str_voice_1602331_43 = "Acho que ainda preciso de mais treinamento...",
  str_voice_1602331_44 = "Gostaria de saber se posso fazer essas decorações usando alquimia?",
  str_voice_1602331_45 = "Obrigado! Era exatamente isso que eu estava procurando!",
  str_voice_1602331_46 = "Uau! Mal posso esperar para usar isso!",
  str_voice_1602331_47 = "O que é isso? Que comovente...",
  str_voice_1602331_48 = "Eu não estava esperando um presente tão maravilhoso hoje!",
  str_voice_1602331_49 = "Três anos atrás, eu não sabia nada sobre alquimia. Eu era apenas uma simples garota da fazenda encontrando maneiras de me divertir todos os dias.",
  str_voice_1602331_50 = "Heheh, essa não é minha primeira vez aventurando em outro mundo... é por isso que não estou muito surpreso com a maioria das coisas aqui!",
  str_voice_1602331_51 = "Sempre mantenha seu desejo por aventura e nunca esqueça dos amigos que você fez ao longo do caminho.",
  str_voice_1602331_52 = "Alchemy Stars!",
  str_voice_1602331_53 = "Você aí!",
  str_voice_1602331_54 = "Bom dia.",
  str_voice_1602331_55 = "Hã? Já é meio-dia?!",
  str_voice_1602331_56 = "Tenha uma boa noite de sono!",
  str_voice_1602331_57 = "Feliz Ano Novo! Estamos todos animados para ver quais aventuras este ano tem reservado para nós!",
  str_voice_1602341_1 = "Desculpe, não estou interrompendo nada, estou? Me perdoe, eu só queria dizer o quão incrível é ver o mundo do topo da sua Colossus.",
  str_voice_1602341_2 = "Maravilhoso! Agora, meus amigos e eu teremos ainda mais aventuras para relembrar... tudo graças a você.",
  str_voice_1602341_3 = "Costumo ouvir uma bela música fluindo através da Colossus... Espere, você quer dizer que eu também posso participar?",
  str_voice_1602341_4 = "A senhorita Connolly parece ter algo para me dizer, o que é perfeito porque eu adoraria ver seus instrumentos... Mas como devo me aproximar dela...",
  str_voice_1602341_5 = "Você quer aprender comigo a pensar como um comerciante para que possa atender às demandas da Senhorita Vice e se defender dos esquemas de marketing do Sr. Jomu? Hehe, estou feliz que você tenha tanta confiança em mim.",
  str_voice_1602341_6 = "Sinta-se à vontade para me confiar qualquer trabalho de suporte. Eu posso não ser tão animado quanto Ryza ou Patty, mas ainda posso realizar muitas coisas dentro da minha especialidade.",
  str_voice_1602341_7 = "Você parece exausto; gostaria de fazer uma pequena pausa? Posso providenciar chá e lanches, se estiver interessado.",
  str_voice_1602341_8 = "Lutando para gerenciar as despesas da sua missão? Acontece que eu tenho alguma experiência em tais assuntos... Talvez eu possa ajudar?",
  str_voice_1602341_9 = "Aprendi várias receitas de Astra com nossos amigos a bordo do Colossus hoje. Mal posso esperar para experimentá-las algum dia!",
  str_voice_1602341_10 = "Volume de entrada... volume de saída... contagem de pedidos... Ah! Minhas desculpas, eu sei que não deveria estar fazendo isso durante meu tempo livre.",
  str_voice_1602341_11 = "Obrigado por depositar sua confiança em mim. Enquanto ainda estamos em seu mundo, por favor, permita-me ajudá-lo com suas finanças.",
  str_voice_1602341_12 = "Depois de discutir o planejamento de viagem e a segurança com Ms. Blanc, sinto que aprendi muitas coisas. É realmente assim que os aurorianos vivem neste mundo...?",
  str_voice_1602341_13 = "Você acha que eu tenho potencial para me tornar um líder da guilda Umbraton? Que gentileza da sua parte dizer isso... Mas eu sou relativamente novo no mundo dos negócios e ainda tenho muito a aprender.",
  str_voice_1602341_14 = "Obrigado pela sua generosidade, Navegador! Você tem trabalhado tão duro para garantir nossa segurança e diversão, e nós fizemos memórias tão maravilhosas. Eu só espero que possamos retribuir o favor algum dia!",
  str_voice_1602341_15 = "Feliz aniversário, Navegador! Ryza e Patty prepararam este presente para você, mas fui eu quem propôs a ideia. Espero que seja do seu agrado!",
  str_voice_1602341_16 = "Você parece bastante ocupado hoje... Gostaria de ajuda?",
  str_voice_1602341_17 = "Bom dia, Navegador! Preparei uma xícara de chá para você.",
  str_voice_1602341_18 = "Bem vindo de volta. Como vai hoje? Viu algo interessante?",
  str_voice_1602341_19 = "Está um pouco tarde para histórias, mas sempre há amanhã. Boa noite!",
  str_voice_1602341_20 = "A capital do meu mundo é uma cidade maravilhosa e movimentada, mas frequentemente me vejo ansiando pelos meus dias de aventura, desfrutando da natureza com Ryza.",
  str_voice_1602341_21 = "Muitos dos nossos amigos Aurorianos sugeriram que eu tentasse trabalhar em Umbraton por um tempo. Você acha que eu realmente tenho o que é preciso para conseguir lá?",
  str_voice_1602341_22 = "A Guilda Valentz, à sua disposição! ...Algo assim, você supõe?",
  str_voice_1602341_23 = "Apesar da ameaça desses monstros, as pessoas deste mundo continuam a sobreviver e levar vidas significativas. É verdadeiramente admirável...",
  str_voice_1602341_24 = "Ryza sempre diz que não entende muito além da alquimia, mas nunca me decepciono enquanto ela está ao meu lado.",
  str_voice_1602341_25 = "Patty está sempre preocupada que ela não é educada o suficiente... Mas eu acho que ela é uma jovem nobre perfeitamente bem-educada.",
  str_voice_1602341_26 = "Ir em aventuras com Ryza... e todos os outros. Esse é o maior tesouro que eu poderia pedir.",
  str_voice_1602341_27 = "Eu também quero contribuir, assim como todos os outros. Eu sou muito mais maduro do que costumava ser, então, por favor, deixe-me assumir mais responsabilidades.",
  str_voice_1602341_28 = "Há algo quase caprichoso nisso... Um lugar verdadeiramente confortável onde os amigos são sempre bem-vindos.",
  str_voice_1602341_29 = "Com licença, eu sou Klaudia Valentz. Astra é totalmente novo para mim. Eu realmente agradeço sua orientação!",
  str_voice_1602341_30 = "Parece que melhorei um pouco.",
  str_voice_1602341_31 = "Ainda posso lutar!",
  str_voice_1602341_32 = "Eu devo continuar treinando.",
  str_voice_1602341_33 = "Eu vou te proteger.",
  str_voice_1602341_34 = "Eu... farei o meu melhor!",
  str_voice_1602341_35 = "Fadas, me guie!",
  str_voice_1602341_36 = "Vento, empreste-me sua força!",
  str_voice_1602341_37 = "Não tem como evitar o vento!",
  str_voice_1602341_38 = "Isso acaba agora! Requiem Branco!",
  str_voice_1602341_39 = "Ataque!",
  str_voice_1602341_40 = "Turbilhão!",
  str_voice_1602341_41 = "(Respire fundo) Eu tenho isso!",
  str_voice_1602341_42 = "Excelente trabalho, pessoal!",
  str_voice_1602341_43 = "Devo permanecer calmo e curar os feridos...",
  str_voice_1602341_44 = "Obrigado por ser um anfitrião adorável. Também preparei alguns refrescos para todos...",
  str_voice_1602341_45 = "Obrigada pelo presente.",
  str_voice_1602341_46 = "Ah, você não deveria!",
  str_voice_1602341_47 = "A-Na verdade, eu também tenho algo...",
  str_voice_1602341_48 = "Posso... Posso mesmo ter isso? Ah, obrigado!",
  str_voice_1602341_49 = "Nasci em uma família de comerciantes viajantes, então passei grande parte da minha infância acompanhando meu pai em suas jornadas. Como resultado, raramente fiz amigos da minha idade.",
  str_voice_1602341_50 = "Ryza e seus amigos salvaram minha vida na floresta um dia. Somos amigos desde então, vivendo todos os tipos de aventuras juntos.",
  str_voice_1602341_51 = "Embora eu ainda esteja seguindo os passos do meu pai como comerciante, acredito que minhas experiências com Ryza me mudaram de várias maneiras diferentes.",
  str_voice_1602341_52 = "Alchemy Stars.",
  str_voice_1602341_53 = "Desculpe-nos...",
  str_voice_1602341_54 = "Bom dia.",
  str_voice_1602341_55 = "Gostaria de um chá?",
  str_voice_1602341_56 = "Please get some rest.",
  str_voice_1602341_57 = "Outro ano novo. May suas fantásticas aventuras continuem bem no futuro, e trazem ainda mais memórias maravilhosas.",
  str_voice_1502351_1 = "Então essa é a sua Colossus! Tudo, desde a forma até a estrutura, é absolutamente impressionante... Eu não vou me perder lá dentro, vou?",
  str_voice_1502351_2 = "Está decidido. Pretendo estudar etiqueta com os cavaleiros de Lumopolis, bem como liderança com os oficiais da Federação Illumina.",
  str_voice_1502351_3 = "Hum, não tenho certeza de quais tipos de jogos as crianças aurorianas gostam. Seria ok se eu me juntasse a eles?",
  str_voice_1502351_4 = "Meu pai já foi um cavaleiro excelente. Para manter a sua honra e a honra da minha família, eu devo continuar treinando.",
  str_voice_1502351_5 = "Ah, então você notou que eu também estive observando a Senhora Carleen? É porque eu quero aprender seu comportamento digno e me aproximar do meu eu ideal.",
  str_voice_1502351_6 = "Participei de várias batalhas não convencionais desde que chegamos ao seu mundo. Espero que essas experiências guiem minha espada para servir bem a você e ao seu Colossus.",
  str_voice_1502351_7 = "Ah, desculpe por deixar você ver um lado tão embaraçoso de mim. Vou me certificar de manter a compostura na próxima vez.",
  str_voice_1502351_8 = "Você acha que minhas habilidades com a espada melhoraram muito? Obrigado! Parece que meu treinamento recente não foi totalmente em vão.",
  str_voice_1502351_9 = "Você me impressiona, Navegador. Sempre que não sei o que fazer, você está sempre lá para me ajudar. Com certeza retribuirei o favor na próxima vez.",
  str_voice_1502351_10 = "... Por que você não está dizendo nada? Eu sabia. Você acha que eu sou chato, não é? ...Não? Tem certeza? Ok...",
  str_voice_1502351_11 = "Entendo. Enquanto estivermos aqui, eu juro protegê-lo como um cavaleiro dedicado a seu serviço.",
  str_voice_1502351_12 = "Eu costumava pensar que os Blue Puni eram monstros tão problemáticos, mas depois de ver os Eclipsitas do seu mundo, eles me parecem perfeitamente dóceis agora.",
  str_voice_1502351_13 = "Um dos seus amigos aurorianos me ofereceu associação ao que parecia ser algum tipo de clube de leitura. Ele parecia muito amigável e conhecedor, mas eu mal conseguia entender qualquer coisa que ele disse.",
  str_voice_1502351_14 = "Se não fosse por Klaudia, tenho certeza de que estaria cometendo muitos erros embaraçosos de compra no seu mundo...",
  str_voice_1502351_15 = "Feliz aniversário! O que você acha do seu presente? Klaudia teve a ideia, e Ryza montou a maior parte. Espero que minha contribuição não diminua a qualidade geral.",
  str_voice_1502351_16 = "Obrigado por me convidar para uma refeição. A culinária de Astra é tão diversa quanto deliciosa.",
  str_voice_1502351_17 = "Bom dia. Você também é uma pessoa muito pontual, hein?",
  str_voice_1502351_18 = "Está ficando tarde. A menos que você planeje ficar de vigia esta noite, talvez devêssemos voltar para o Colosso?",
  str_voice_1502351_19 = "Hmm... Ah, Navegador! Você voltou tarde! Deixe-me ajudar com esses suprimentos.",
  str_voice_1502351_20 = "Nada me deixaria mais feliz do que simplesmente contribuir à minha maneira.",
  str_voice_1502351_21 = "A arquitetura de Lumopolis é esplêndida, mas a Senhora Carleen tem um bom argumento: para realmente entender um domínio, deve-se olhar além de sua aparência.",
  str_voice_1502351_22 = "Se você tentar me impedir, não vou me segurar!",
  str_voice_1502351_23 = "São criaturas estranhas, o que só me faz pensar: Ryza tentará usá-las como materiais em sua alquimia?",
  str_voice_1502351_24 = "Este mundo está cheio de todos os tipos de novos materiais! Com um pouco de pesquisa, Ryza provavelmente poderia criar alguns explosivos extraordinários a partir deles.",
  str_voice_1502351_25 = "Há uma Auroriana na Colossus que carrega um longo instrumento para onde quer que vá. É sempre divertido vê-la e Klaudia se encarando sem dizer uma palavra!",
  str_voice_1502351_26 = "No passado, eu teria dito algo como \"trazer honra ao meu pai e à nossa família\". Mas agora, quero pensar em algo diferente.",
  str_voice_1502351_27 = "Eca, eu odeio insetos! Eu sei que eles não podem me machucar, mas só de ouvir as asas deles batendo faz meu cabelo ficar em pé.",
  str_voice_1502351_28 = "É uma criação magnífica com valor prático e estético.",
  str_voice_1502351_29 = "Prazer em conhecê-lo. Meu nome é Patricia Abelheim, mas você pode me chamar de Patty. Embora minha família não seja a mais proeminente, eu venho da nobreza e possuo alguma habilidade com a espada. Confio que meus talentos possam ser úteis para você.",
  str_voice_1502351_30 = "Hmm, fiquei mais forte.",
  str_voice_1502351_31 = "Vou ficar ainda mais forte.",
  str_voice_1502351_32 = "Este deve ser o ritmo da aventura.",
  str_voice_1502351_33 = "Vou valorizar toda a experiência que adquiri aqui.",
  str_voice_1502351_34 = "Mais experiência para ganhar.",
  str_voice_1502351_35 = "Deixa comigo.",
  str_voice_1502351_36 = "Não há escapatória!",
  str_voice_1502351_37 = "Desaparece no desespero!",
  str_voice_1502351_38 = "Toma essa! Desejo Impecável!",
  str_voice_1502351_39 = "Toma essa!",
  str_voice_1502351_40 = "Tente e me pare!",
  str_voice_1502351_41 = "Hm... É minha honra!",
  str_voice_1502351_42 = "Não há tempo para descansar sobre os meus louros.",
  str_voice_1502351_43 = "... Devemos recuar por enquanto.",
  str_voice_1502351_44 = "Essas decorações não são nada como as da minha cidade natal, mas eu aprecio a beleza delas da mesma forma.",
  str_voice_1502351_45 = "Lembrarei de sua generosidade. Obrigado.",
  str_voice_1502351_46 = "Uau, isso é...?",
  str_voice_1502351_47 = "Eu gostaria de fazer mais por você também.",
  str_voice_1502351_48 = "Jamais esquecerei deste instante!",
  str_voice_1502351_49 = "Sou descendente de uma linhagem nobre. Embora eu seja a filha mais nova da minha família, entendo a importância da minha posição social, bem como meu status como filha de um senhor.",
  str_voice_1502351_50 = "Devo me comportar de acordo com os padrões da nobreza e fazer tudo ao meu alcance para aliviar o fardo do meu pai... Mesmo que isso me traga tristeza e solidão.",
  str_voice_1502351_51 = "Ryza me ensinou como o povo comum vive e me ajudou a entender o significado de aventura.",
  str_voice_1502351_52 = "Alchemy Stars.",
  str_voice_1502351_53 = "Perdoe-me-",
  str_voice_1502351_54 = "É tão cedo.",
  str_voice_1502351_55 = "Muito bem!",
  str_voice_1502351_56 = "Já está tão tarde!",
  str_voice_1502351_57 = "May você realize todos os seus objetivos este ano e encontre novos para perseguir... Feliz Ano Novo!",
  str_voice_1602333_1 = "Mesmo tendo crescido cercado por lagos, o vasto mar é algo de que nunca me cansarei de ver!",
  str_voice_1602333_2 = "Navegador, esse tecido não parece exatamente com Eldrocode? Ah, desculpe... Você provavelmente nem sabe o que é isso...",
  str_voice_1602333_3 = "Há tantas coisas interessantes sobre os oceanos de Astra! Por exemplo... Os ouriços-do-mar aqui realmente vivem no mar!",
  str_voice_1602333_10 = "O que é aquilo flutuando em nossa direção? É um barril!",
  str_voice_1602333_11 = "\"Quanto mais reveladora a armadura, melhor sua defesa\"? É-Esse é realmente o funcionamento aqui em Astra?!",
  str_voice_1602333_12 = "Ufa! Isso foi divertido e tudo mais, mas eu realmente preciso me refrescar agora! Tem algo que eu possa usar, Navegador?",
  str_voice_1602333_13 = "Ahh... Passar o verão com amigos é o melhor!",
  str_voice_1602333_14 = "Bahahaha! Você está totalmente encharcado, Navegador! Ainda bem que estamos de trajes de banho, certo... E-Ei! Ataques surpresa não são justos!",
  str_voice_1602333_16 = "O mar está nos chamando para começar uma nova aventura!",
  str_voice_1602333_17 = "Bom dia! Você dormiu bem? A brisa fresca na Colossus quase me faz esquecer que é verão lá embaixo!",
  str_voice_1602333_18 = "Gostaria de uma bebida agradável e refrescante? Ahh... Não tenho meus ingredientes habituais, mas ainda tem um ótimo sabor!",
  str_voice_1602333_19 = "Atchim! Fica um pouco frio à noite na Colossus, né? Oh, esse cobertor é para mim? Obrigado!",
  str_voice_1602333_35 = "Hora da aventura!",
  str_voice_1602333_36 = "Para o oceano!",
  str_voice_1602333_37 = "Suma para o outro lado do mar!",
  str_voice_1602333_38 = "Eu não vou perder para ninguém neste verão!",
  str_voice_1602333_39 = "Como é isso?!",
  str_voice_1602333_40 = "Decolar!",
  str_voice_1602333_44 = "Zarpe para outra incrível aventura de verão!",
  str_voice_1602371_1 = "Você toca piano? Perfeito! Eu toco concha! Vamos tocar juntos alguma vez!",
  str_voice_1602371_2 = "... Onde eu estava mesmo? Ah, você toca algum instrumento? Quer aprender a tocar a concha comigo?",
  str_voice_1602371_3 = "Quer ler juntos? Não conheço muitas palavras, então, você poderia ler para mim? Yay! Obrigado!",
  str_voice_1602371_4 = "Minha força é a sua força! Basta dizer a palavra!",
  str_voice_1602371_5 = "A melodia da concha me transporta para os sonhos do meu venerado antepassado. Aquelas bolhas são na verdade sua risada - ele tem sido de grande ajuda para mim.",
  str_voice_1602371_6 = "PlayerName, você tem cheiro de um sonho. Não tenha medo, eu vou tocar a concha se eles se recusarem a ficar longe de você...",
  str_voice_1602371_7 = "Você é muito gentil comigo... É verdade, eu posso sentir isso!",
  str_voice_1602371_8 = "Eu gosto de você! Huh? Por que estás a corar?",
  str_voice_1602371_9 = "Eu gosto de você! Hã? Por que está olhando para o outro lado? Hmm... Parece que estou esquecendo de algo. Bem, tanto faz! Eu só gosto de você!",
  str_voice_1602371_10 = "Está fazendo uma pausa? Gostaria de ter um bom sonho? Eu posso te ajudar com isso.",
  str_voice_1602371_11 = "Ok! Deixe-me saber se eu esquecer alguma coisa!",
  str_voice_1602371_12 = "Aprendi um novo truque, PlayerName! Espere aí por um momento, que eu vou te mostrar!",
  str_voice_1602371_13 = "Meus pais estão dormindo, e eu vivo dentro dos sonhos deles. Eles virão com meu ancestral para brincar comigo uma vez que eu também vá dormir.",
  str_voice_1602371_14 = "PlayerName, eu ajudei muitas mais pessoas hoje. Olha! Apenas olhe para estas pequenas flores vermelhas que eles deixaram no meu caderno... Huh? Você quer dizer... estas são de ontem?",
  str_voice_1602371_15 = "Feliz aniversário! Sou grato pelo seu nascimento e gosto de você.",
  str_voice_1602371_16 = "Ei! Quer sair juntos?",
  str_voice_1602371_17 = "Ei! Posso ajudar em alguma coisa?",
  str_voice_1602371_18 = "Ah! Quer observar a lua?",
  str_voice_1602371_19 = "Bocejo... Estou me sentindo sonolenta. Não fique acordado até tarde, ok?",
  str_voice_1602371_20 = "Todos em Harbour City foram tão gentis comigo, então farei o meu melhor para ajudá-lo a protegê-la, Elvis!",
  str_voice_1602371_21 = "Aquela mulher da True Order deseja descobrir o que está além da bolha, mas rompê-la despertará todos.",
  str_voice_1602371_22 = "Só quando eu adormecer é que o mundo perceberá que é apenas um sonho.",
  str_voice_1602371_23 = "A bolha ilusória está ligeiramente manchada. Esses rebeldes estão tendo pesadelos, e eles estão fazendo outros terem pesadelos também.",
  str_voice_1602371_24 = "Eu gosto de Connolly porque a música dela é tão doce para o ouvido.",
  str_voice_1602371_25 = "Eu gosto de Zeta porque ela sempre me dá doces quando passa por mim. Hã? Por que eu me lembro? Bobo PlayerName, é porque eu esqueci de comer o doce, é claro.",
  str_voice_1602371_26 = "O café gelado é delicioso. Não consigo evitar de beber demais.",
  str_voice_1602371_27 = "Como recuso comida picante sem chatear os outros?",
  str_voice_1602371_28 = "Nos meus sonhos, meu ancestral sempre me carrega para voar, mas ele não tem tantos quartos.",
  str_voice_1602371_29 = "Eu me lembro de você, PlayerName. Eu escrevi sobre você no meu caderno. Você gostaria de dar uma olhada, você diz? Sem espiar! Até eu tenho o direito de manter um ou outro segredo aqui e ali.",
  str_voice_1602371_30 = "Meu ancestral está me chamando em sonhos.",
  str_voice_1602371_31 = "Os problemas são passageiros.",
  str_voice_1602371_32 = "O destino é apenas uma bolha do meu ancestral.",
  str_voice_1602371_33 = "O mundo pode ser o meu sonho.",
  str_voice_1602371_34 = "Eu posso ajudar.",
  str_voice_1602371_35 = "Vamos!",
  str_voice_1602371_36 = "Meu ancestral está despertando.",
  str_voice_1602371_37 = "Vamos lá! Ataque!",
  str_voice_1602371_38 = "Vamos! É o final!",
  str_voice_1602371_39 = "Ritmo de bolha.",
  str_voice_1602371_40 = "Luz de bolha.",
  str_voice_1602371_41 = "Eu vou te proteger.",
  str_voice_1602371_42 = "Hehe! Graças a Deus você está ileso!",
  str_voice_1602371_43 = "Ajude-me, ancestral.",
  str_voice_1602371_44 = "Isso é um monte de livros! Tem algum conto de fadas? Eu quero ler alguns.",
  str_voice_1602371_45 = "Não esquecerei de sua gentileza.",
  str_voice_1602371_46 = "Você é o meu doce sonho.",
  str_voice_1602371_47 = "Obrigado! Você está me fazendo corar!",
  str_voice_1602371_48 = "Gostei! Isso faz meu coração bater forte!",
  str_voice_1602371_49 = "Ainda me lembro de como minha mãe costumava pegar minha mão e me contar um conto de fadas todas as noites. Conforme o barco balançava com as ondas, ela logo adormecia.",
  str_voice_1602371_50 = "Encontrei esta concha com meu pai. Apenas a peguei quando ouvi alguém me chamar, e pude tocá-la por instinto. Ela me levou ao meu ancestral em sonhos.",
  str_voice_1602371_51 = "Às vezes, posso encontrar meu ancestral mesmo sem tocar a concha. Parece que está me guiando para consertar um sonho muito, muito grande. Hã? O que pode acontecer com o mundo se todos acordarem?",
  str_voice_1602371_52 = "Alquimia... Hmm... Ah! Alquimia Estrelas!",
  str_voice_1602371_53 = "Bolha!",
  str_voice_1602371_54 = "Sol brilhante.",
  str_voice_1602371_55 = "Sentindo preguiça.",
  str_voice_1602371_56 = "Você teve um sonho?",
  str_voice_1602371_57 = "Hoje é o dia mais especial de todos! Tenho tantos presentes para você! Por favor, passe o dia comigo!",
  str_voice_1702361_1 = "Há muito tempo, o reino precisava de estrelas para despedaçar a escuridão, então meus camaradas bravamente se adiantaram e se queimaram... Suas cinzas permanecem como poeira estelar, e o tempo nunca apagará essas almas nobres.",
  str_voice_1702361_2 = "Nossa antiga camarada Celestita, Ludweiss... Ela fez o sacrifício supremo por nós. Continuarei seu legado, mesmo que eu seja o único que se lembra.",
  str_voice_1702361_3 = "Friegson é uma criança difícil. Como Adras, ela nunca teve uma infância feliz e nem sequer tem alguém especial para lembrar. Não culpe a atitude dela, ela está apenas exausta.",
  str_voice_1702361_4 = "Obrigado, Celestita. Você ajudou com todos os nossos arrependimentos e me permitiu cumprir minha promessa - de me reunir com meus camaradas.",
  str_voice_1702361_5 = "Sei que todos os Celestitas são amigáveis, e lamento muito por ter você em nossa luta. Juro que nunca permitirei que você se torne o sacrifício.",
  str_voice_1702361_6 = "O Último Celestita... Que apelido triste. Você também tem esperado sozinho, na esperança de encontrar seus companheiros? Não pareça tão desolado. Se eu posso me reunir com meus camaradas, talvez você possa encontrar os seus também. Deixe-nos ajudar.",
  str_voice_1702361_7 = "Descanse, sinta o vento da liberdade e ouça a música da vida.",
  str_voice_1702361_8 = "Em nome de Aquiles, eu vou te proteger.",
  str_voice_1702361_9 = "Eu costumava ser capaz de usar magia, mas hoje em dia este corpo não recebe mais a bênção de Lumina. Não importa, porém. Mesmo que eu caia no abismo, ainda posso convocar a luz das estrelas para resistir ao destino.",
  str_voice_1702361_10 = "A força que me envolve... Eu a chamo de Poder Estelar, pois frequentemente sussurra para mim, contando-me sobre cenas estreladas.",
  str_voice_1702361_11 = "Outro celestita me encontrou depois de Ludweiss. Ele não tinha visto a luz da esperança, como Ludweiss, mas estava igualmente determinado a queimar sua alma. Eles são os verdadeiros heróis, e eu devo cantar suas façanhas.",
  str_voice_1702361_12 = "Aqueles obcecados por lucro ou poder não são aptos para nos julgar, muito menos para registrar nossas histórias com sua visão limitada!",
  str_voice_1702361_13 = "Permaneceremos fiéis a nós mesmos, mantendo a guarda silenciosa e lutando para sempre contra o mal. Assim tem sido por dois milênios, e assim será por mais dois.",
  str_voice_1702361_14 = "Eu não era corajoso o suficiente naquela época, o que causou tanta tragédia para meus camaradas. Mas, felizmente, ainda há aqueles que nos amam, e eles passaram a tocha e nos permitiram nos encontrar novamente. Eu devo tanto a você e não posso dizer o quanto sou grato...",
  str_voice_1702361_15 = "Feliz aniversário. Eu consegui que Adras me ensinasse a fazer um bolo para você.",
  str_voice_1702361_16 = "Alguma coisa que gostaria de compartilhar?",
  str_voice_1702361_17 = "Nunca pensei que veria o sol novamente.",
  str_voice_1702361_18 = "Quer se aquecer perto da fogueira?",
  str_voice_1702361_19 = "Está tarde. Cuidado com essas vozes. Não confie precipitadamente nessas vozes em sua cabeça, especialmente à noite.",
  str_voice_1702361_20 = "Caçador Silencioso é um título que pensei ter enterrado. Ele representa muitas coisas... heroísmo, sacrifício, traição e... esperança.",
  str_voice_1702361_21 = "Northland? Ah... O reino agora vive à luz da paz e da boa sorte, e isso é suficiente.",
  str_voice_1702361_22 = "Somos observadores da justiça.",
  str_voice_1702361_23 = "Eles não são nossos únicos inimigos, mas são os únicos que eu desejo apontar minha espada.",
  str_voice_1702361_24 = "Ludweiss adorava manter registros, e eu prometi a ela que continuaria com tudo. Hoje em dia, amo o mundo em nome dela.",
  str_voice_1702361_25 = "Não tenha medo dos meus camaradas. Abaixe suas armas, eles são apenas um padeiro, uma garota alegre, um guarda nervoso e alguém que anseia pela paz.",
  str_voice_1702361_26 = "Todos vivem felizes aqui, obrigado.",
  str_voice_1702361_27 = "Livros hoje em dia até glorificam vilões. Eu não entendo...",
  str_voice_1702361_28 = "Você tem sorte de poder realizar atos justos com seus amigos.",
  str_voice_1702361_29 = "Celestita... Ah, perdoe-me. Há muito tempo, nossos nobres camaradas celestitas sacrificaram tudo por nós. Agora eu vou proteger o último de sua espécie.",
  str_voice_1702361_30 = "Rica escuridão, à minha disposição.",
  str_voice_1702361_31 = "Tenha cuidado, Celestita.",
  str_voice_1702361_32 = "Poder Estelar Abundante.",
  str_voice_1702361_33 = "Poder transbordante...",
  str_voice_1702361_34 = "Luz estelar escura, irrompa!",
  str_voice_1702361_35 = "Meteoro inflexível, resista ao destino!",
  str_voice_1702361_36 = "Aniquilar!",
  str_voice_1702361_37 = "Morte a todos os inimigos!",
  str_voice_1702361_38 = "Faz muito tempo desde que me chamaram de capitão.",
  str_voice_1702361_39 = "Todos ilesos, certo?",
  str_voice_1702361_40 = "Proteja o Celestita. Eu vou cobrir a retaguarda!",
  str_voice_1702361_41 = "Saudações. Estou gravando novas informações.",
  str_voice_1702361_42 = "Obrigado, Celestita.",
  str_voice_1702361_43 = "Não é surpreendente, já que é de um Celestita que pode ler mentes.",
  str_voice_1702361_44 = "Vou registrar sua gentileza.",
  str_voice_1702361_45 = "Não tenho nada em troca... a menos que você queira ver minhas anotações?",
  str_voice_1702361_46 = "Há muito, muito tempo atrás, eu era chamado de Mão do Rei. Eu agi com lealdade e convicção e lutei incansavelmente pelo reino. Meu amigo próximo estava no trono naquela época, e foi ele quem apoiou meu eu intransigente.",
  str_voice_1702361_47 = "Desde quando fiquei apenas com amigos? Eu não sei. Talvez tenha sido minha postura inabalável que fez todos me verem como um inimigo, mas a única coisa que eu não podia aceitar era a traição do rei.",
  str_voice_1702361_48 = "Mais tarde, escolhi selar meus camaradas, mas não esperava que o preço fosse o sacrifício do meu amigo. Jurei garantir um futuro para eles, então devo permanecer no passado... Não fique triste, pois se você me vê agora, significa que já atravessei os anos.",
  str_voice_1702361_49 = "Alchemy Stars.",
  str_voice_1702361_50 = "Celestita.",
  str_voice_1702361_51 = "Bom dia.",
  str_voice_1702361_52 = "O sol está tão deslumbrante.",
  str_voice_1702361_53 = "Você também deveria descansar um pouco.",
  str_voice_1702361_54 = "Além dos anos passados, está o novo futuro. Mantenha a fé de que mais coisas boas acontecerão.",
  str_voice_1602381_1 = "Ainda estou aprendendo como equilibrar ser um Mensageiro e também ser um defensor da justiça.",
  str_voice_1602381_2 = "Por favor, não revele meu segredo para Tweety. Eu não quero que ela veja minhas asas reais ainda.",
  str_voice_1602381_3 = "O Cresta Estrela neste colar era originalmente um talismã dado ao nosso clã pelo Senhor Aquiles, mas agora se tornou um símbolo de nossa proteção. Eu sei que esse tipo de lealdade cega deve parecer bobo para você, mas não poderia estar mais orgulhoso da minha herança.",
  str_voice_1602381_4 = "Lâminas escondidas entre penas e asas ocultas sob capas. Assim como meu disfarce, a história do clã Longinus é afiada e profunda.",
  str_voice_1602381_5 = "Talvez seja porque tenho desempenhado tantos papéis e conhecido tantas pessoas que consigo me dar bem com quase todos. Mas, dada a escolha, sempre optarei por aqueles que me fazem sentir em casa.",
  str_voice_1602381_6 = "Um dia, vou desenhar minha própria lâmina final do Brasão de Estrela.",
  str_voice_1602381_7 = "Para manter nossas identidades ocultas, o clã Longinus nunca residiu em um lugar por muito tempo, ou estabeleceu laços estreitos com estranhos, aliás. Mas por causa de você, estou livre agora... Embora eu ainda não esteja acostumado com isso.",
  str_voice_1602381_8 = "Você quer ouvir o quê? Sem chance! Isso é só quando estou tentando esconder quem eu realmente sou... Você quer voltar a ser estranhos?",
  str_voice_1602381_9 = "No dia em que você me libertou da obrigação do meu clã, fiz um novo voto para mim mesmo. Jurei testemunhar o caminho que seu futuro toma e ver até onde sua luz alcança.",
  str_voice_1602381_10 = "... Sentindo-se cansado? Tudo bem, eu suponho que uma pausa em um horário razoável não é uma violação do acordo. Bom trabalho hoje.",
  str_voice_1602381_11 = "Só para deixar claro - Você quer que eu supervisione seu trabalho. Isso está correto?",
  str_voice_1602381_12 = "A bondade da Senhora Freya é impressionante, até para mim... Parece que ainda tenho muito a aprender.",
  str_voice_1602381_13 = "As penas do corvo não são totalmente pretas. Se você olhar de perto, pode ver a cor escondida dentro... Qual é o problema? Eu pensei que discernir luz e cores era a sua especialidade?",
  str_voice_1602381_14 = "Os Guerreiros Estelares parecem sentir culpa em relação ao nosso clã, principalmente o Lord Aquiles... Se possível, por favor, convença-os de que não há necessidade de se sentirem arrependidos, e que ajudá-los tem sido a nossa maior honra.",
  str_voice_1602381_15 = "Feliz aniversário. Hmm? Não fique tão surpreso. Jurei lembrar deste dia pelo resto da minha vida e oferecer meus melhores votos a você todos os anos.",
  str_voice_1602381_16 = "Gostaria de experimentar um ambiente de trabalho verdadeiramente diverso?",
  str_voice_1602381_17 = "Você acordou cedo. Você também tem uma grande quantidade de trabalho para fazer?",
  str_voice_1602381_18 = "Bem feito. Só para que você saiba, seus esforços não passam despercebidos.",
  str_voice_1602381_19 = "É hora do corvo explorar os arredores... É melhor se você não perguntar. Boa noite.",
  str_voice_1602381_20 = "A Courier Union tem acesso a todos os tipos de inteligência, mas nunca espiona essas informações ou as divulga para ninguém. É o lugar perfeito para eu ficar escondido.",
  str_voice_1602381_21 = "Se não fosse pelo controle do Shadowlord, todo Umbraton cairia em completo pandemônio. Afinal, pessoas sem fé não representam nada. Umbraton deveria agradecê-lo por instilar um senso de dignidade nesta cidade.",
  str_voice_1602381_22 = "Somos os mais leais guardiões de segredos.",
  str_voice_1602381_23 = "Essas criaturas frias da escuridão são completamente desprovidas de emoção e autoconsciência. Infelizmente, em sua essência, eles não são diferentes de nós.",
  str_voice_1602381_24 = "Goldie e eu não somos iguais. Ela é um pássaro cantor que prospera à luz do dia, enquanto eu sou um corvo que caça no meio da noite. Só chegamos a nos conhecer através de um encontro casual à noite.",
  str_voice_1602381_25 = "Tweety genuinamente ama seu trabalho como mensageira, e sua felicidade é quase avassaladora. Só de vê-la pode alegrar o dia de qualquer um.",
  str_voice_1602381_26 = "Cuidadosamente pintando estas lâminas de preto, deixando-as secar, escondendo-as em minhas penas... Acho tudo isso muito relaxante.",
  str_voice_1602381_27 = "Por que Kleken gosta tanto de mentir? Nunca vou entender esse cara.",
  str_voice_1602381_28 = "A brisa a bordo da Colossus é tão agradável. Eu me pergunto... O Sr. Czerny riu quando finalmente conseguiu voar pelos céus?",
  str_voice_1602381_29 = "Não tenha medo, Último Celestita. A partir deste momento, você nunca mais estará sozinho. Eu juro me tornar sua força orientadora, sua fonte de força. E sim, este é o meu voto para você.",
  str_voice_1602381_30 = "Minhas asas ficam mais afiadas.",
  str_voice_1602381_31 = "Para os perversos, eu sou a morte.",
  str_voice_1602381_32 = "Eu sou o corvo da noite.",
  str_voice_1602381_33 = "Sou o guardião da fé.",
  str_voice_1602381_34 = "Bando.",
  str_voice_1602381_35 = "Uma revelação de mil anos...",
  str_voice_1602381_36 = "A orientação chegou.",
  str_voice_1602381_37 = "O destino do clã Longinus está em jogo!",
  str_voice_1602381_38 = "Grave este cometa em sua alma.",
  str_voice_1602381_39 = "As asas negras do quietus.",
  str_voice_1602381_40 = "Morte instantânea.",
  str_voice_1602381_41 = "Eu não deveria liderar.",
  str_voice_1602381_42 = "O segredo foi mantido.",
  str_voice_1602381_43 = "Voe, seu tolo.",
  str_voice_1602381_44 = "Este é um bom lugar para descansar minhas asas.",
  str_voice_1602381_45 = "Obrigado.",
  str_voice_1602381_46 = "Como você sabia que eu gosto disso?",
  str_voice_1602381_47 = "Com certeza retribuirei o favor.",
  str_voice_1602381_48 = "Como sempre... Obrigado.",
  str_voice_1602381_49 = "Eu estava treinando sob Queen Bethlehem quando meus pais morreram defendendo Umbraton, mas Sua Majestade se recusou a me deixar sair do Northland para procurá-los. Além da minha missão, meu coração estava cheio de tanta raiva naquela época. Raiva em relação aos Eclipsitas, raiva em relação ao Queen, e raiva em relação aos meus pais por me mandarem embora...",
  str_voice_1602381_50 = "Por algum tempo, duvidei de mim mesmo enquanto lutava para proteger o segredo dos Guerreiros Estelares. Com Eraveil desaparecida e a profecia quebrada, pelo que eu ainda estava lutando? Essa confusão... só deu origem a ainda mais raiva.",
  str_voice_1602381_51 = "Algumas pessoas afirmam que sou um herói da noite em Umbraton, mas isso não poderia estar mais longe da verdade. Ao contrário de Goldie, que luta pela justiça à noite, estou apenas descontando minha raiva nos criminosos da cidade... Se eu não mudar em breve, posso desenvolver um gosto por esse tipo de violência algum dia.",
  str_voice_1602381_52 = "Alchemy Stars.",
  str_voice_1602381_53 = "Olá.",
  str_voice_1602381_54 = "Anime-se um pouco.",
  str_voice_1602381_55 = "Tão quente aqui.",
  str_voice_1602381_56 = "Ainda acordado?",
  str_voice_1602381_57 = "Com a chegada de um novo ano, que você se liberte das armadilhas do passado e caminhe para um futuro melhor.",
  str_voice_1602183_1 = "Qualquer coisa na vida pode ser vista de diferentes perspectivas. Pense nisso, mesmo que eu acabe fazendo alguém perder o emprego, eles provavelmente acabarão com um melhor e um chefe melhor também - ou seja, eu.",
  str_voice_1602183_2 = "May Eu pergunto por que você está me encarando, meu querido? Quer dizer, eu pareço muito mais jovem agora? Meu, que homem jovem de fala mansa você é... Por que você não se aproxima um pouco e vê se eu realmente mudei tanto assim?",
  str_voice_1602183_3 = "Você vai me conhecer em breve, querida, não há pressa. Confie em mim, continue trabalhando duro ao meu lado e você descobrirá antes que perceba.",
  str_voice_1602183_10 = "Ufa... Que dia corrido! Eu realmente mataria por um banho agora. Eu digo, patinho de borracha, aí vou eu!",
  str_voice_1602183_11 = "Oh, querido, é sempre um prazer encontrar com você. Diga-me, há algo mais que você gostaria de aprender sobre negócios hoje?",
  str_voice_1602183_12 = "O líder de uma guilda não é nada menos que o rosto que mostra ao mundo! Não importa o que se possa estar contemplando por dentro, deve-se sempre mostrar uma boa aparência para o público. Então, minha querida, dê-me sua opinião honesta - o que você acha do perfume que estou usando hoje?",
  str_voice_1602183_13 = "No mundo dos negócios, é essencial manter uma postura respeitosa. Dito isto, não hesitarei em tomar uma atitude se alguém se recusar a ouvir a razão.",
  str_voice_1602183_14 = "Minha estratégia de negócios não é sobre espremer até o último bit de lucro que posso - é sobre fazer grandes ganhos em pequenos investimentos. Eu sou como você, minha querida - nós dois amamos criar milagres, e somos bons nisso.",
  str_voice_1602183_16 = "Hah, lá está você, minha querida! Que tal eu começar a administrar sua propriedade, sim?",
  str_voice_1602183_17 = "Oh céus, você chegou tão cedo hoje - que coisa mais séria você é. Lembre-se, querido, a paciência é uma virtude. Coisas boas vêm para aqueles que esperam.",
  str_voice_1602183_18 = "Que timing perfeito. Seria um prazer convidá-lo para jantar. Você acha que terá tempo?",
  str_voice_1602183_19 = "Ficar acordado até tão tarde para cumprimentar a velha eu? Querido, estou começando a questionar suas intenções.",
  str_voice_1602183_35 = "Prepare-se para ser adquirido.",
  str_voice_1602183_36 = "Não hesite.",
  str_voice_1602183_37 = "Tome isso—meu selo de desaprovação!",
  str_voice_1602183_38 = "Agora, venda-me sua alma!",
  str_voice_1602183_39 = "Hora de se ramificar!",
  str_voice_1602183_40 = "Uma aquisição muito agradável!",
  str_voice_1602183_44 = "Querido, você não acha que este lugar está começando a parecer mais com o meu estilo?",
  str_voice_1602183_58 = "A Guilda Cloudrover está aberta para negócios.",
  str_voice_1602183_59 = "Como você gostaria de ver o mundo comigo?",
  str_voice_1602183_60 = "Bom dia, querido!",
  str_voice_1602183_61 = "Deixei um presente na sua mesa de trabalho.",
  str_voice_1602183_62 = "Dirigíveis não são nada como Colossus - especialmente quando o sol está a pino.",
  str_voice_1602183_63 = "Ai meu... Você nem vai me convidar para sentar um pouco?",
  str_voice_1602183_64 = "Vi você lá, no convés, parado na brisa. Há algo te incomodando?",
  str_voice_1602183_65 = "Aposto que você está louco para me dar uma massagem, não está, querido?",
  str_voice_1602183_66 = "Que noite divina é esta.",
  str_voice_1602183_67 = "\"Ações falam mais alto do que palavras.\"",
  str_voice_1602183_68 = "Se você deseja ter sucesso em Umbraton, a credibilidade é tudo.",
  str_voice_1602183_69 = "Invista na Guilda Cloudrover—confie em mim, você não vai se arrepender.",
  str_voice_1602183_70 = "Aproveite o momento - pode muito bem ser o momento que muda sua vida.",
  str_voice_1602183_71 = "As oportunidades são fugazes - é por isso que agarro todas elas com ambas as mãos.",
  str_voice_1600014_1 = "Como eu disse antes, este vestido é para uma dança especial, e já que você está bem aí... Eu poderia mostrá-lo para você, se você quiser? Mas só para que você saiba, é uma dança para duas pessoas.",
  str_voice_1600014_2 = "Oh, Nepólis, quando você estará livre do espelho e voltará ao nosso mundo? Sinto falta de ver nossos vestidos balançando para lá e para cá enquanto dançamos juntas...",
  str_voice_1600014_3 = "As flores ao redor do Lago Espelho parecem tão vibrantes como sempre, mesmo quando estou longe. Alguém está cuidando delas por mim?",
  str_voice_1600014_10 = "\"Lembra daquelas lindas flores brancas? Elas cresceram juntas, lado a lado, suas raízes entrelaçadas, compartilhando a mesma luz do sol e chuva.\"",
  str_voice_1600014_11 = "Por favor, não olhe por muito tempo para o espelho. Mesmo com minha irmã e eu aqui, os segredos contidos neste artefato não devem ser menosprezados.",
  str_voice_1600014_12 = "Minha irmã e eu... Apesar de sermos gêmeas, mal somos iguais. Eu sempre fui a quieta e melancólica... É por isso que sinto tanta falta dela.",
  str_voice_1600014_13 = "Minha irmã e eu estamos inextricavelmente conectadas. Desde nossas almas e memórias até nossos Luminatics, compartilhamos todas as nossas bênçãos, mas também sofremos igualmente com o vazio de nossa separação.",
  str_voice_1600014_14 = "Minha irmã gosta muito de você... Hã? Não me diga que você esqueceu da flor que ela te deu? E caso esteja curioso sobre como eu sei disso, é porque minha irmã e eu estamos conectados de coração e mente.",
  str_voice_1600014_16 = "Por favor, não se preocupe comigo, sinto-me perfeitamente descansado agora.",
  str_voice_1600014_17 = "Desculpe, mas se eu me perder no espelho novamente, preciso que você me acorde e me mantenha acordado.",
  str_voice_1600014_18 = "Acho que ouvi minha irmã te chamando agora mesmo.",
  str_voice_1600014_19 = "Estou aqui para te importunar, obviamente. Considere isso uma vingança por me provocar mais cedo.",
  str_voice_1600014_35 = "O Espelho Geminos, juntos para sempre.",
  str_voice_1600014_36 = "Nepolis, empreste-me sua força—",
  str_voice_1600014_37 = "Flores brancas desabrochando na neve negra!",
  str_voice_1600014_38 = "Uma promessa feita diante do espelho.",
  str_voice_1600014_39 = "Como um poema...",
  str_voice_1600014_40 = "Como uma fábula...",
  str_voice_1600014_44 = "Narcisos brancos, lírios, jacintos, lírios do vale... Ah, e não vamos esquecer desses dentes-de-leão.",
  str_voice_1600014_58 = "O mundo dentro do espelho é perigoso, mas felizmente, você está aqui.",
  str_voice_1600014_59 = "Acho que vi um lado completamente diferente da rainha dentro do mundo do espelho... Isso é um segredo entre vocês dois?",
  str_voice_1600014_60 = "Você está certo, não importa mais se ela é minha irmã de verdade ou apenas uma manifestação do poder do espelho.",
  str_voice_1600014_61 = "Tenho meu próprio papel na proteção de Northland, então nunca vou renunciar ao poder do espelho.",
  str_voice_1600014_62 = "Eu me considerava o guardião do Lago Espelho, mas nunca percebi que o lago estava me protegendo o tempo todo.",
  str_voice_1600014_63 = "O que exatamente está dentro do espelho?",
  str_voice_1600014_64 = "Um mundo de sonhos seria diferente do mundo dentro do espelho?",
  str_voice_1600014_65 = "Só espero que meu vestido não fique molhado.",
  str_voice_1600014_66 = "São esses Cristais de Gelo? Ou talvez Cromera?",
  str_voice_1600014_67 = "Isso mesmo. Nepolis e eu... nós sempre estaremos juntos.",
  str_voice_1600014_68 = "Uma garota misteriosa e um espelho ainda mais misterioso... Quem no mundo é você?",
  str_voice_1600014_69 = "Não... Não minhas memórias... Nepolis!!!",
  str_voice_1600014_70 = "Sua Majestade está me protegendo... E minha irmã, Nepolis, também!",
  str_voice_1600014_71 = "Lago Espelho... Vamos escrever um fim para o nosso poema de uma vez por todas.",
  str_voice_1602411_1 = "Não é justo que eu seja o único com um coração mecânico. Por que não faço um para você também? Confie em mim, é incrível!",
  str_voice_1602411_2 = "Zoom! Veja o quão longe meu avião de papel pode voar! Legal, né? Aposto que até poderia acompanhar seu Colossus!",
  str_voice_1602411_3 = "\"Dê-me liberdade ou dê-me a morte!\" Essa é uma das minhas citações favoritas de todos os tempos. De nada!",
  str_voice_1602411_4 = "Por que não fazemos algo incomum? Talvez devêssemos roubar algo de Illumina... Ou melhor ainda, invadir Lumopolis e vandalizar suas estátuas sofisticadas!",
  str_voice_1602411_5 = "Ninguém pode me dizer o que fazer porque sou eu quem dá as ordens por aqui! Bem... Ninguém exceto a Senhora Victoria, claro. Ela basicamente sabe tudo.",
  str_voice_1602411_6 = "Enquanto meu coração ainda estiver batendo e meu corpo ainda estiver reagindo, eu não pertenço a ninguém!",
  str_voice_1602411_7 = "Uau! Hahaha, te assustei? Não se preocupe, eu não mordo... Pelo menos não sem um bom motivo!",
  str_voice_1602411_8 = "Acha que pode me ensinar a pilotar a Colossus? Nós viajamos muito devagar! Eu posso levá-la além dos seus limites! Não? Ah, vamos lá, pensei que éramos amigos!",
  str_voice_1602411_9 = "Deixe-me contar um pequeno segredo: você é o tipo perfeito de amigo para mim. Você se preocupa comigo sem estar constantemente se metendo nos meus assuntos, então... Obrigado por tudo.",
  str_voice_1602411_10 = "Ugh, vou começar a brotar corais de tão abafado que está aqui...",
  str_voice_1602411_11 = "Eu, ajudar você? Você é quem trabalha para mim! Vou ficar de olho em você, então nada de moleza!",
  str_voice_1602411_12 = "Isso mesmo, sou o infame infiltrador de Illumina e o bombástico ladrão de Lumópolis! Vá em frente, deleite seus olhos com esta lenda viva diante de você! Eu posso lidar com isso!",
  str_voice_1602411_13 = "A lealdade importa muito na amizade, então se você precisar de ajuda, Petey e eu sempre estaremos lá para você! Você sente o mesmo, certo? Ótimo! Então, você poderia me emprestar um pouco de dinheiro? Eu quero comprar algo.",
  str_voice_1602411_14 = "Pepita Felice é apenas um nome que uso para assustar as pessoas. É incrível como as pessoas te tratam melhor quando você tem um sobrenome que soa nobre. Estúpido, certo?",
  str_voice_1602411_15 = "Parabéns pra você, nessa data querida! E então? Você gostou?",
  str_voice_1602411_16 = "Você chegou bem na hora para uma grandiosa nova aventura!",
  str_voice_1602411_17 = "Esteja sempre preparado para que nunca perca nenhuma diversão!",
  str_voice_1602411_18 = "A comida mais saborosa é a que você compartilha com amigos!",
  str_voice_1602411_19 = "Todas as coisas divertidas tendem a acontecer por volta dessa hora.",
  str_voice_1602411_20 = "A Verdade não prende ninguém, é por isso que a Senhora Victoria me deixa fazer o que eu quero.",
  str_voice_1602411_21 = "Os cães de Lumópolis continuam me perseguindo, e os falcões de Illumina são astutos pra caramba. Melhor ficar alerta.",
  str_voice_1602411_22 = "Eu sou Pepita, luz da liberdade e uma criança da Verdade!",
  str_voice_1602411_23 = "Honestamente, eu não me importaria de brincar com eles se todos fossem tão divertidos quanto Ursura.",
  str_voice_1602411_24 = "A Senhora Victoria me deu a chave para a felicidade. Ela me conhece muito bem, mas ainda é um pouco reservada.",
  str_voice_1602411_25 = "Ursura é tão louca quanto eu, é por isso que somos tão bons amigos!",
  str_voice_1602411_26 = "Ahhh! Vocês fazem bebidas matadoras no Colossus!",
  str_voice_1602411_27 = "Muitos oficiais de Illumina por aqui, você não acha? Mal consigo respirar de tanta tensão!",
  str_voice_1602411_28 = "Vou usar a Colossus para explodir qualquer um que atrapalhe meu caminho! Haha, estou brincando! Alivie um pouco!",
  str_voice_1602411_29 = "Certo, vamos tirar as apresentações do caminho. O nome é Pepita, e não, eu não sou \"aquela garota\" ou \"aquele pequeno ser\", mas Pepita. Pepita a Lutadora.",
  str_voice_1602411_30 = "Mais rápido! Mais rápido!",
  str_voice_1602411_31 = "Meu coração está em chamas!",
  str_voice_1602411_32 = "A surra nunca para!",
  str_voice_1602411_33 = "Eu sou uma chama dançante!",
  str_voice_1602411_34 = "Pepi...TA!",
  str_voice_1602411_35 = "Meu coração está batendo ainda mais rápido!",
  str_voice_1602411_36 = "Meu sangue tá fervendo!",
  str_voice_1602411_37 = "Floresça livremente!",
  str_voice_1602411_38 = "Vamos incendiar o mundo!",
  str_voice_1602411_39 = "Queime até virar cinzas!",
  str_voice_1602411_40 = "Hora para o grande final!",
  str_voice_1602411_41 = "Deixe com o grande Pepita!",
  str_voice_1602411_42 = "Vê? Perfeição caótica.",
  str_voice_1602411_43 = "Vamos, vamos sair daqui!",
  str_voice_1602411_44 = "N-Na verdade, eu tenho um pouco de medo de altura... Brincadeira! Haha, enganei você, não foi? Ahh, você deveria ver a expressão no seu rosto!",
  str_voice_1602411_45 = "Ei, isso não é tão ruim assim!",
  str_voice_1602411_46 = "Eu simplesmente amo isso!",
  str_voice_1602411_47 = "Tentando me bajular de novo?",
  str_voice_1602411_48 = "Ótimo, agora eu tenho que te dar algo em troca!",
  str_voice_1602411_49 = "Como todos em Illumina, tive uma infância bastante difícil. Meu pai... Ah, odeio chamá-lo assim. De qualquer forma, esse covarde é o motivo pelo qual minha mãe morreu, e também por que acabei no laboratório.",
  str_voice_1602411_50 = "O Comitê substituiu meu coração por um artificial para me controlar, mas ainda consegui escapar. Mais tarde, conheci a Senhora Victoria e aventurei-me pela Zona Cega sozinho. Belisaria estava errado... Eu não sou um defeito.",
  str_voice_1602411_51 = "Não importa o que aconteça, nunca vou abaixar a cabeça para ninguém! Um dia, vou recuperar meu coração e caçar o cara que me traiu!",
  str_voice_1602411_52 = "Ta-da! Alchemy Stars!",
  str_voice_1602411_53 = "Ei!",
  str_voice_1602411_54 = "Você acordou cedo.",
  str_voice_1602411_55 = "Eu quero almoçar!",
  str_voice_1602411_56 = "Hora de causar alguns problemas!",
  str_voice_1602411_57 = "Vamos fazer uma festa de dança louca para comemorar o ano novo! Ah, quase me esqueci: Feliz Ano Novo!",
  str_voice_1701103_1 = "Aventura no sonho é interessante, certo? Lembre-se de me levar com você na próxima, mas não se for para um dos outros Caçadores Silenciosos. Os sonhos deles provavelmente seriam muito escuros.",
  str_voice_1701103_2 = "Tudo bem, como recompensa pela nossa longa amizade, vou ouvir sua confissão agora... Hã? Por que você ainda está parado? Eu nem sempre tenho tempo livre, então comece a confessar!",
  str_voice_1701103_3 = "Pare! Eu já sei o que você está prestes a dizer, e a resposta é não: só porque eu sou a \"Santinha Silenciosa\" não significa que eu tenha que ficar quieta o tempo todo. Títulos não devem ser levados ao pé da letra, sabe?",
  str_voice_1701103_10 = "Hum? O que há com essa expressão vazia no seu rosto? Não me diga... minha aura santa está te deixando sem palavras?",
  str_voice_1701103_11 = "Ah, então o poderoso Navegador finalmente reconhece minha grandeza e veio buscar meu sábio conselho! O que é isso? Você só precisa de ajuda com seu trabalho? Ugh... Que decepcionante.",
  str_voice_1701103_12 = "Embora Northland seja um lugar frio e inóspito, o povo de lá sempre avançou através do vento e da neve. Tenho orgulho de desempenhar o papel de salvador para pessoas fortes e trabalhadoras como essas.",
  str_voice_1701103_13 = "Meus camaradas e eu passamos por tudo: tempestades uivantes, tempestades furiosas, frio extremo e inúmeros ataques de Eclipsitas. A grandeza do nosso tipo não reside nas bênçãos do divino, mas nos incêndios inextinguíveis que ardem em nossos corações.",
  str_voice_1701103_14 = "Por gerações, as Santas Silenciosas queimaram suas vidas para ajudar os outros, razão pela qual nunca viveram por muito tempo. Comparada a elas, eu tive uma vida longa e feliz, mesmo tendo apenas dezenove anos!",
  str_voice_1701103_16 = "Ainda andando de um lado para o outro a essa hora, hein? Parece que até mesmo o grande Navegador tem dificuldades para fazer seus próprios planos. Como a pessoa mais inteligente e madura aqui, permita-me ajudá-lo.",
  str_voice_1701103_17 = "Deixe-me ficar na cama! Já cumpri meus deveres santos, agora me deixe em paz!",
  str_voice_1701103_18 = "Estou indo comer com todos os outros. Gostaria de se juntar a nós? Adras está cozinhando hoje, sabia!",
  str_voice_1701103_19 = "Por que você ainda está vagando assim? Quer ouvir uma história para dormir? Se sim, vá perguntar a Cynthia.",
  str_voice_1701103_35 = "Prepare-se para a explosão.",
  str_voice_1701103_36 = "Permita-me interceder.",
  str_voice_1701103_37 = "Purificado pelo trovão!",
  str_voice_1701103_38 = "Deixem todos ficarem em silêncio—!",
  str_voice_1701103_39 = "Monte a tempestade!",
  str_voice_1701103_40 = "Comande o trovão!",
  str_voice_1701103_44 = "Então é assim que a paz se sente... Incrível.",
  str_voice_1701103_58 = "Trovão! E então, silêncio!",
  str_voice_1701103_59 = "Uma festa?! Onde?!",
  str_voice_1701103_60 = "Hmm, essa é a única razão pela qual me dei ao trabalho de vir.",
  str_voice_1701103_61 = "Que tal um pouco de treinamento de combate, Navegador? Prometo pegar leve se você fizer o mesmo.",
  str_voice_1701103_62 = "Freya, a lança mais afiada dos Caçadores Silenciosos, chegou!",
  str_voice_1701103_63 = "Freya o Impecável chegou!",
  str_voice_1701103_64 = "Hã? Para onde todos foram?",
  str_voice_1701103_65 = "Eca... É realmente tão longe assim? Eu teria trazido um cavalo se soubesse disso.",
  str_voice_1701103_66 = "Ah, que bela pequena surpresa. O grande Freya humildemente aceita o seu presente."
}
return config
